-- =====================================================================
-- Mise à jour n°8 du 30/10/2026 : argumentaire détaillé (replié sur la fiche)
--   - besoin détaillé : Situation / Difficulté / Attente
--   - pour chaque parcours : un « argumentaire détaillé » ; « pourquoi » court reformulé pour certains parcours de second choix
--   - M1 des parcours IA et M1 Base des réseaux sociaux : un argument commun, non lié au métier
-- À coller dans Supabase › SQL Editor › New query, puis « Run ». Le relancer ne change rien de plus.
-- Ne remplace rien de ce que vous avez modifié dans Gestion : un texte n'est changé que s'il est encore identique à l'ancien.
-- =====================================================================
update public.profils p set data = p.data
    || case when coalesce(p.data->'besoinDetail', 'null'::jsonb) = 'null'::jsonb then jsonb_build_object('besoinDetail', v.bd) else '{}'::jsonb end
    || jsonb_build_object('parcours', coalesce((
         select jsonb_agg(
                  case when u.x is null then t.e
                       else t.e
                         || case when coalesce(t.e->>'argumentaire', '') = '' and coalesce(u.x->>'argumentaire', '') <> '' then jsonb_build_object('argumentaire', u.x->>'argumentaire') else '{}'::jsonb end
                         || case when t.e->>'pourquoi' = u.x->>'old' then jsonb_build_object('pourquoi', u.x->>'new') else '{}'::jsonb end
                  end order by t.o)
         from jsonb_array_elements(p.data->'parcours') with ordinality as t(e, o)
         left join lateral (select x from jsonb_array_elements(v.pc) as y(x) where y.x->>'formation' = t.e->>'formation' limit 1) as u(x) on true
       ), p.data->'parcours', '[]'::jsonb))
    || case when v.code is not null and v.m1new is not null and (p.data->'reponses'->>v.code) is not distinct from v.m1old
            then jsonb_build_object('reponses', coalesce(p.data->'reponses', '{}'::jsonb) || jsonb_build_object(v.code, v.m1new)) else '{}'::jsonb end,
  updated_at = now()
from (values
  ('bur-001', $j${"situation": "Produit chaque mois tableaux de bord, reportings et analyses à partir de plusieurs exports.", "difficulte": "Copier-coller et retraitements manuels, risques d'erreur, fichiers lourds à mettre à jour.", "attente": "Des tableaux de bord fiables qui se mettent à jour seuls, et plus de temps pour l'analyse."}$j$::jsonb, $j$[{"formation": "bur-excel-power", "old": "Le plus adapté : analyse et tableaux de bord.", "new": "Le plus adapté : analyse et tableaux de bord.", "argumentaire": "Il apprend à importer, nettoyer et croiser ses données avec Power Query, puis à construire tableaux croisés et tableaux de bord avec Power Pivot et Power BI. Résultat : un reporting qui se met à jour en un clic, sans copier-coller."}, {"formation": "bur-vba", "old": "Pour automatiser ses traitements récurrents.", "new": "À proposer pour automatiser ses traitements récurrents (mises en forme, imports, éditions) avec des macros VBA, en complément de ses tableaux de bord.", "argumentaire": ""}]$j$::jsonb, null, null, null),
  ('bur-002', $j${"situation": "Prépare régulièrement les mêmes tableaux : suivis, états, extractions mises en forme.", "difficulte": "Tâches répétitives et chronophages, refaites à la main chaque semaine ou chaque mois.", "attente": "Automatiser ces traitements pour gagner du temps et fiabiliser les résultats."}$j$::jsonb, $j$[{"formation": "bur-vba", "old": "Le plus adapté : automatiser les tâches répétitives.", "new": "Le plus adapté : automatiser les tâches répétitives.", "argumentaire": "Les macros VBA automatisent mises en forme, imports et éditions répétés chaque semaine ou chaque mois. Résultat : plusieurs heures gagnées et moins d'erreurs."}, {"formation": "bur-excel-power", "old": "Pour consolider plusieurs fichiers.", "new": "Pour consolider plusieurs fichiers.", "argumentaire": "Power Query les consolide automatiquement."}]$j$::jsonb, null, null, null),
  ('bur-003', $j${"situation": "Suit des indicateurs commerciaux, RH ou de paie pour sa direction ou ses équipes.", "difficulte": "Ressaisie des données depuis plusieurs sources, tableaux vite dépassés.", "attente": "Des tableaux de bord clairs, à jour en un clic, sans ressaisie."}$j$::jsonb, $j$[{"formation": "bur-excel-power", "old": "Le plus adapté : tableaux de bord automatisés.", "new": "Le plus adapté : tableaux de bord automatisés.", "argumentaire": "Il construit des tableaux de bord et des indicateurs alimentés automatiquement par ses sources (Power Query, tableaux croisés, Power BI). Résultat : des chiffres à jour en un clic, sans ressaisie."}]$j$::jsonb, null, null, null),
  ('cao-001', $j${"situation": "Dessine des plans de bâtiment dans un bureau d'études, une entreprise du BTP ou chez un architecte.", "difficulte": "Plans à produire vite et sans erreur ; clients et maîtres d'ouvrage qui attendent aussi des vues 3D.", "attente": "Produire des plans 2D cotés fiables et présenter les projets en 3D."}$j$::jsonb, $j$[{"formation": "cao-autocad", "old": "Le plus adapté : plans 2D cotés et mis en page.", "new": "Le plus adapté : plans 2D cotés et mis en page.", "argumentaire": "Il apprend à dessiner, coter et mettre en page des plans techniques 2D conformes, prêts à transmettre. Résultat : des plans fiables, produits plus vite."}, {"formation": "cao-sketchup", "old": "Pour présenter les projets en 3D.", "new": "À proposer pour présenter les projets en 3D aux clients et maîtres d'ouvrage.", "argumentaire": ""}]$j$::jsonb, null, null, null),
  ('cao-002', $j${"situation": "Conçoit des aménagements intérieurs, cuisines ou agencements et les présente aux clients.", "difficulte": "Le client a du mal à se projeter sur un plan ; les rendus prennent du temps.", "attente": "Modéliser vite en 3D pour convaincre, puis produire les plans de réalisation."}$j$::jsonb, $j$[{"formation": "cao-sketchup", "old": "Le plus adapté : modélisation 3D accessible.", "new": "Le plus adapté : modélisation 3D accessible.", "argumentaire": "SketchUp permet de modéliser rapidement pièces, mobilier et aménagements en 3D, sans compétences techniques poussées. Résultat : le client visualise son projet et décide plus vite."}, {"formation": "cao-autocad", "old": "Pour les plans techniques de réalisation.", "new": "À proposer pour produire ensuite les plans 2D cotés destinés à la réalisation et aux artisans.", "argumentaire": ""}]$j$::jsonb, null, null, null),
  ('cao-003', $j${"situation": "Conçoit des pièces mécaniques et des assemblages dans un bureau d'études industriel.", "difficulte": "Besoin d'un outil 3D paramétrique et de mises en plan conformes pour la fabrication.", "attente": "Maîtriser la conception 3D de pièces et d'assemblages et produire les plans."}$j$::jsonb, $j$[{"formation": "cao-solidworks", "old": "Le plus adapté : conception mécanique 3D.", "new": "Le plus adapté : conception mécanique 3D.", "argumentaire": "Il apprend à modéliser pièces et assemblages en 3D paramétrique et à produire les mises en plan pour la fabrication."}, {"formation": "cao-autocad", "old": "Pour les plans 2D.", "new": "À proposer pour les plans techniques 2D et la reprise de plans existants.", "argumentaire": ""}]$j$::jsonb, null, null, null),
  ('cao-004', $j${"situation": "Artisan du bois ou du métal qui fabrique sur mesure : menuiserie, agencement, métallerie.", "difficulte": "Dessins à la main ou approximatifs, difficile de montrer le résultat au client avant fabrication.", "attente": "Dessiner ses ouvrages pour les présenter, les chiffrer et les fabriquer avec précision."}$j$::jsonb, $j$[{"formation": "cao-sketchup", "old": "Le plus adapté pour le bois et l’agencement.", "new": "Le plus adapté pour le bois et l’agencement.", "argumentaire": "Modéliser ses ouvrages en 3D pour les présenter au client et préparer leur fabrication."}, {"formation": "cao-solidworks", "old": "Pour la métallerie et la fabrication de pièces.", "new": "Pour la métallerie et la fabrication de pièces.", "argumentaire": "Conception 3D de pièces et d'assemblages."}, {"formation": "cao-autocad", "old": "Pour des plans de fabrication 2D.", "new": "À proposer s'il a surtout besoin de plans de fabrication 2D cotés.", "argumentaire": ""}]$j$::jsonb, null, null, null),
  ('cao-005', $j${"situation": "En reconversion vers le dessin technique, le bâtiment ou l'industrie.", "difficulte": "Les offres d'emploi exigent la maîtrise d'un logiciel de DAO ou de CAO.", "attente": "Acquérir un logiciel de référence et le prouver par une certification reconnue."}$j$::jsonb, $j$[{"formation": "cao-autocad", "old": "Le logiciel de référence du dessin 2D.", "new": "Le logiciel de référence du dessin 2D.", "argumentaire": "Le logiciel de référence du dessin technique 2D, le plus demandé dans les offres d'emploi. La certification ICDL rend la compétence visible sur son CV."}, {"formation": "cao-sketchup", "old": "Pour l’aménagement et le bâtiment.", "new": "Pour l’aménagement et le bâtiment.", "argumentaire": "Une modélisation 3D accessible et rapide à prendre en main."}, {"formation": "cao-solidworks", "old": "Pour l’industrie.", "new": "Pour l’industrie.", "argumentaire": "La conception mécanique 3D de pièces et d'assemblages."}]$j$::jsonb, null, null, null),
  ('col-001', $j${"situation": "Petite équipe ou TPE qui adopte, ou vient d'adopter, les outils Google.", "difficulte": "Documents envoyés par mail, versions multiples, agendas non partagés, visios improvisées.", "attente": "Partager documents, agendas et réunions simplement, et travailler à plusieurs sur les mêmes fichiers."}$j$::jsonb, $j$[{"formation": "col-workspace", "old": "Le plus adapté : toute la suite Google.", "new": "Le plus adapté : toute la suite Google.", "argumentaire": "Toute la suite Google en pratique (Gmail, Drive, Agenda, Meet, Docs, Sheets) pour partager les documents, coéditer et organiser les réunions. Résultat : une équipe qui travaille sur les mêmes fichiers, sans échanges de pièces jointes."}]$j$::jsonb, null, null, null),
  ('col-002', $j${"situation": "Gère seul(e) clients, projets, tâches et notes.", "difficulte": "Informations dispersées entre carnets, mails et fichiers ; oublis et perte de temps.", "attente": "Centraliser tout son travail dans un seul espace organisé sur mesure."}$j$::jsonb, $j$[{"formation": "col-notion", "old": "Le plus adapté : un espace de travail sur mesure.", "new": "Le plus adapté : un espace de travail sur mesure.", "argumentaire": "Il construit pendant la formation son propre espace Notion (clients, tâches, notes, documents). Résultat : tout son travail centralisé et organisé."}, {"formation": "col-workspace", "old": "S’il travaille avec des clients ou partenaires.", "new": "S’il travaille avec des clients ou partenaires.", "argumentaire": "Partage de documents et organisation des rendez-vous avec les outils Google."}]$j$::jsonb, null, null, null),
  ('col-003', $j${"situation": "Organise l'information et le suivi de l'équipe : procédures, projets, documents partagés.", "difficulte": "Informations éparpillées, procédures introuvables, suivi d'équipe difficile.", "attente": "Centraliser procédures, suivis et documents dans un espace partagé et clair."}$j$::jsonb, $j$[{"formation": "col-notion", "old": "Pour centraliser procédures et suivis.", "new": "Pour centraliser procédures et suivis.", "argumentaire": "Le plus adapté pour centraliser procédures, bases de connaissances et suivis d'équipe dans des pages et bases de données partagées."}, {"formation": "col-workspace", "old": "Si l’entreprise utilise Google.", "new": "Si l’entreprise utilise Google.", "argumentaire": "Organisation collaborative avec Drive, Agenda, Meet et Docs."}]$j$::jsonb, null, null, null),
  ('col-004', $j${"situation": "Salarié(e) ou bénévole d'une association dont l'équipe travaille souvent à distance.", "difficulte": "Peu de moyens, bénévoles dispersés, documents échangés par mail.", "attente": "Travailler à plusieurs avec des outils gratuits et simples : documents, agendas, visios."}$j$::jsonb, $j$[{"formation": "col-workspace", "old": "Le plus adapté : outils gratuits et partagés.", "new": "Le plus adapté : outils gratuits et partagés.", "argumentaire": "Des outils gratuits et partagés (Drive, Docs, Meet) pour faire travailler bureau et bénévoles à distance."}]$j$::jsonb, null, null, null),
  ('com-001', $j${"situation": "Commerçant(e), artisan ou auto-entrepreneur qui communique lui-même.", "difficulte": "Pas de graphiste ni de compétences graphiques ; visuels faits à la va-vite ou jamais faits.", "attente": "Créer seul(e), rapidement, des affiches, publications et flyers d'aspect professionnel."}$j$::jsonb, $j$[{"formation": "com-canva1", "old": "Le plus adapté : visuels sans compétences graphiques.", "new": "Le plus adapté : visuels sans compétences graphiques.", "argumentaire": "En une journée, il apprend à créer affiches, publications et flyers professionnels à partir de modèles, sans compétences graphiques. Résultat : une communication régulière et soignée."}]$j$::jsonb, null, null, null),
  ('com-002', $j${"situation": "Produit les visuels de communication de la structure : réseaux sociaux, affiches, supports.", "difficulte": "Volume de visuels en hausse, cohérence graphique difficile à tenir.", "attente": "Produire plus vite des visuels cohérents avec la charte."}$j$::jsonb, $j$[{"formation": "com-canva1", "old": "S’il débute sur Canva.", "new": "S’il débute sur Canva.", "argumentaire": "Des bases solides pour produire des visuels professionnels."}, {"formation": "com-canva-pro", "old": "S’il utilise déjà Canva.", "new": "S’il utilise déjà Canva.", "argumentaire": "Kit de marque, modèles d'équipe, vidéo, IA et automatisation pour produire plus vite des visuels cohérents."}]$j$::jsonb, null, null, null),
  ('com-003', $j${"situation": "Salarié(e) ou bénévole qui fait la communication des événements de l'association.", "difficulte": "Pas de budget ni de graphiste ; supports réalisés avec les moyens du bord.", "attente": "Créer soi-même, gratuitement, des affiches et publications attractives."}$j$::jsonb, $j$[{"formation": "com-canva1", "old": "Le plus adapté : simple et gratuit.", "new": "Le plus adapté : simple et gratuit.", "argumentaire": "Simple et gratuit pour les associations ; il crée affiches, invitations et publications pour ses événements."}]$j$::jsonb, null, null, null),
  ('com-004', $j${"situation": "Utilise déjà Canva régulièrement en entreprise.", "difficulte": "N'exploite qu'une partie des fonctions ; temps perdu à refaire les mêmes déclinaisons ; image peu homogène.", "attente": "Gagner du temps avec le kit de marque, les modèles, la vidéo et l'IA de Canva Pro."}$j$::jsonb, $j$[{"formation": "com-canva-pro", "old": "Le plus adapté : exploiter Canva Pro.", "new": "Le plus adapté : exploiter Canva Pro.", "argumentaire": "Il exploite tout Canva Pro (kit de marque, modèles partagés, vidéo, IA, automatisation des déclinaisons). Résultat : du temps gagné et une image homogène."}]$j$::jsonb, null, null, null),
  ('ia-001', $j${"situation": "Passe une grande partie de ses journées à rédiger : courriers, comptes rendus de réunion, synthèses de documents longs, mails.", "difficulte": "Tâches répétitives et chronophages ; peur de mal utiliser l'IA ou d'y confier des informations confidentielles.", "attente": "Gagner du temps tout de suite sur ses propres écrits, avec une méthode simple et sûre."}$j$::jsonb, $j$[{"formation": "ia-admin", "old": "Le plus adapté : les écrits du quotidien.", "new": "Le plus adapté : les écrits du quotidien.", "argumentaire": "Il part de ses écrits réels. Le M2 lui fait produire comptes rendus, synthèses et courriers, puis créer son propre assistant de comptes rendus de réunion ; le M3 ajoute la mise en forme visuelle de ses supports. Résultat : des modèles réutilisables dès le retour au poste."}]$j$::jsonb, $j$M1$j$, $j$Comprendre comment fonctionne l'IA, pratiquer les bases sur ses propres écrits, et savoir quelles informations ne jamais confier à un outil.$j$, $j$Comprendre le fonctionnement de l'IA générative, rédiger des prompts efficaces, comparer les outils (ChatGPT, Mistral, Gemini, Claude…) et adopter les bons réflexes : limites, éthique et sécurité des données.$j$),
  ('ia-002', $j${"situation": "Partage son temps entre prospection, rendez-vous, propositions commerciales et relances.", "difficulte": "La préparation et le suivi écrits lui prennent du temps au détriment du terrain ; relances irrégulières.", "attente": "Préparer plus vite ses rendez-vous et produire des propositions et relances personnalisées, dans son style."}$j$::jsonb, $j$[{"formation": "ia-admin", "old": "Propositions, relances et préparation de rendez-vous.", "new": "Propositions, relances et préparation de rendez-vous.", "argumentaire": "Le M2 travaille sur ses vrais dossiers : préparation de rendez-vous, propositions commerciales, relances et emailings, puis un assistant personnalisé qui rédige dans son style. Le M3 lui permet de créer seul(e) visuels et supports de présentation. Résultat : moins de temps derrière l'écran, plus sur le terrain."}]$j$::jsonb, $j$M1$j$, $j$Comprendre comment l'IA produit ses réponses pour mieux les cadrer ; bases pratiques ; éthique et sécurité des données clients.$j$, $j$Comprendre le fonctionnement de l'IA générative, rédiger des prompts efficaces, comparer les outils (ChatGPT, Mistral, Gemini, Claude…) et adopter les bons réflexes : limites, éthique et sécurité des données.$j$),
  ('ia-003', $j${"situation": "Traite chaque jour des demandes clients : commandes, devis, réclamations, suivi de livraison.", "difficulte": "Volume de réponses écrites important, ton à ajuster, données clients à protéger.", "attente": "Répondre plus vite et plus juste, avec des réponses types fiables et des règles claires sur les données."}$j$::jsonb, $j$[{"formation": "ia-admin", "old": "Relation client et sécurisation des données.", "new": "Relation client et sécurisation des données.", "argumentaire": "Le M2 construit des réponses types fiables et un assistant nourri de ses procédures, avec les règles RGPD : données à ne jamais saisir, anonymisation, vérification. Résultat : des réponses plus rapides et sûres."}]$j$::jsonb, $j$M1$j$, $j$Fonctionnement de l'IA et limites à connaître en relation client ; bases pratiques ; sécurité des données clients.$j$, $j$Comprendre le fonctionnement de l'IA générative, rédiger des prompts efficaces, comparer les outils (ChatGPT, Mistral, Gemini, Claude…) et adopter les bons réflexes : limites, éthique et sécurité des données.$j$),
  ('ia-004', $j${"situation": "Gère seul(e) toute son activité : production, devis, factures, mails, communication, prospection.", "difficulte": "Manque de temps pour l'administratif et la communication ; ne sait pas quels outils IA choisir ni quoi leur confier.", "attente": "Déléguer une partie de ces tâches à l'IA pour se recentrer sur son métier, sans risque pour ses clients."}$j$::jsonb, $j$[{"formation": "ia-admin", "old": "Gestion, devis, mails et prospection au quotidien.", "new": "Gestion, devis, mails et prospection au quotidien.", "argumentaire": "Le parcours couvre tout son quotidien d'indépendant : devis, mails, relances et prospection au M2, avec un assistant qui connaît son offre et ses tarifs ; visuels et contenus audio pour communiquer au M3. Résultat : des modèles utilisables dès le lendemain."}]$j$::jsonb, $j$M1$j$, $j$Comprendre le fonctionnement de l'IA et choisir ses outils ; bases pratiques ; règles de sécurité pour protéger son activité et ses clients.$j$, $j$Comprendre le fonctionnement de l'IA générative, rédiger des prompts efficaces, comparer les outils (ChatGPT, Mistral, Gemini, Claude…) et adopter les bons réflexes : limites, éthique et sécurité des données.$j$),
  ('ia-005', $j${"situation": "Dirige une petite structure et porte lui-même l'administratif, la relation client, la communication, parfois le recrutement.", "difficulte": "Peu de temps et pas de service support ; entend parler de l'IA sans savoir par où commencer ni quels risques elle présente.", "attente": "Savoir ce que l'IA peut faire pour l'entreprise et déléguer rapidement des tâches concrètes, en toute sécurité."}$j$::jsonb, $j$[{"formation": "ia-admin", "old": "Si sa priorité est l'administratif et la relation client.", "new": "Si sa priorité est l'administratif et la relation client.", "argumentaire": "Devis, courriers, mails et organisation au M2, avec un assistant personnalisé ; visuels et contenus audio pour communiquer au M3."}, {"formation": "ia-rh", "old": "S'il gère lui-même le recrutement et le personnel.", "new": "S'il gère lui-même le recrutement et le personnel.", "argumentaire": "Offres d'emploi, fiches de poste, entretiens et cadre RGPD au M2, avec un assistant pour les documents RH. Il repart aussi avec les bases d'une charte d'usage de l'IA pour ses salariés."}]$j$::jsonb, $j$M1$j$, $j$Comprendre ce qu'est l'IA et ce qu'elle change pour l'entreprise ; bases pratiques ; enjeux éthiques, juridiques et de sécurité.$j$, $j$Comprendre le fonctionnement de l'IA générative, rédiger des prompts efficaces, comparer les outils (ChatGPT, Mistral, Gemini, Claude…) et adopter les bons réflexes : limites, éthique et sécurité des données.$j$),
  ('ia-006', $j${"situation": "Conçoit et anime ses formations pour différents clients, souvent seul(e), avec des délais courts.", "difficulte": "La conception de supports, quiz et évaluations prend beaucoup de temps ; ses clients attendent qu'il (elle) maîtrise l'IA.", "attente": "Concevoir plus vite et prouver la mise à jour de ses compétences, avec une certification reconnue."}$j$::jsonb, $j$[{"formation": "ia-form", "old": "Le plus adapté : conception et animation de formations.", "new": "Le plus adapté : conception et animation de formations.", "argumentaire": "Le M2 lui apprend à concevoir scénarios, supports, quiz et évaluations avec l'IA, et à créer ses propres assistants de conception. Le M3 ajoute illustrations, voix off et vidéos avec avatar pour ses supports. La certification valorise sa montée en compétence auprès de ses clients."}]$j$::jsonb, $j$M1$j$, $j$Fonctionnement de l'IA pour l'expliquer à ses apprenants ; bases pratiques ; éthique, droits d'auteur et sécurité des contenus.$j$, $j$Comprendre le fonctionnement de l'IA générative, rédiger des prompts efficaces, comparer les outils (ChatGPT, Mistral, Gemini, Claude…) et adopter les bons réflexes : limites, éthique et sécurité des données.$j$),
  ('ia-007', $j${"situation": "Anime des séquences en organisme de formation, face à des stagiaires qui utilisent déjà l'IA.", "difficulte": "Supports à renouveler, évaluations à repenser (travaux produits par l'IA), questions des stagiaires sur les outils.", "attente": "Intégrer l'IA dans ses séquences et ses évaluations, et savoir encadrer son usage par les stagiaires."}$j$::jsonb, $j$[{"formation": "ia-form", "old": "Pratiques pédagogiques avec l'IA.", "new": "Pratiques pédagogiques avec l'IA.", "argumentaire": "Le M2 traite exactement ses enjeux : concevoir des séquences avec l'IA, repenser l'évaluation quand les stagiaires utilisent l'IA, reconnaître un travail généré et respecter la propriété intellectuelle. Le M3 enrichit ses supports (visuels, audio, avatar). Résultat : des pratiques à jour et un discours clair face aux stagiaires."}]$j$::jsonb, $j$M1$j$, $j$Comprendre le fonctionnement de l'IA pour en parler aux apprenants ; bases pratiques ; éthique, triche et sécurité.$j$, $j$Comprendre le fonctionnement de l'IA générative, rédiger des prompts efficaces, comparer les outils (ChatGPT, Mistral, Gemini, Claude…) et adopter les bons réflexes : limites, éthique et sécurité des données.$j$),
  ('ia-008', $j${"situation": "Prépare cours, exercices et évaluations pour des classes de niveaux hétérogènes.", "difficulte": "Temps de préparation et de correction important ; élèves qui rendent des travaux faits avec l'IA.", "attente": "Préparer plus vite des contenus adaptés au niveau, et savoir repérer et encadrer l'usage de l'IA."}$j$::jsonb, $j$[{"formation": "ia-form", "old": "Préparation de cours et d'évaluations.", "new": "Préparation de cours et d'évaluations.", "argumentaire": "Le M2 lui fait produire cours, exercices différenciés et évaluations à partir de ses propres supports, et aborde la détection des travaux faits par l'IA. Résultat : du temps gagné sur la préparation et la correction."}]$j$::jsonb, $j$M1$j$, $j$Comment fonctionne l'IA, en termes simples ; bases pratiques ; enjeux éthiques, évaluation et protection des données des élèves.$j$, $j$Comprendre le fonctionnement de l'IA générative, rédiger des prompts efficaces, comparer les outils (ChatGPT, Mistral, Gemini, Claude…) et adopter les bons réflexes : limites, éthique et sécurité des données.$j$),
  ('ia-010', $j${"situation": "Forme ses collègues ou accompagne des alternants en plus de son poste.", "difficulte": "Peu de temps pour créer des supports ; modes opératoires et documents internes à transformer en formation.", "attente": "Produire rapidement des supports et des quiz à partir des documents de l'entreprise."}$j$::jsonb, $j$[{"formation": "ia-form", "old": "Concevoir des formations internes.", "new": "Concevoir des formations internes.", "argumentaire": "Le M2 lui montre comment transformer les documents de l'entreprise en supports de formation, quiz et évaluations, avec des assistants dédiés. Le M3 ajoute visuels et capsules audio ou vidéo. Résultat : des formations internes prêtes plus vite, sans être formateur de métier."}]$j$::jsonb, $j$M1$j$, $j$Comprendre le fonctionnement de l'IA ; bases pratiques ; éthique et confidentialité des informations de l'entreprise.$j$, $j$Comprendre le fonctionnement de l'IA générative, rédiger des prompts efficaces, comparer les outils (ChatGPT, Mistral, Gemini, Claude…) et adopter les bons réflexes : limites, éthique et sécurité des données.$j$),
  ('ia-011', $j${"situation": "Porte seul(e) ou presque la fonction RH d'une PME : recrutement, entretiens, notes, plan de formation, relations sociales.", "difficulte": "Beaucoup d'écrits à fort enjeu ; salariés qui utilisent déjà l'IA sans cadre ; données personnelles à protéger (RGPD).", "attente": "Gagner du temps sur les écrits RH et poser un cadre d'usage de l'IA dans l'entreprise (charte, règles)."}$j$::jsonb, $j$[{"formation": "ia-rh", "old": "Le plus adapté : écrits RH et cadre d'usage.", "new": "Le plus adapté : écrits RH et cadre d'usage.", "argumentaire": "Le M2 traite les écrits RH à fort enjeu (contrats, notes, communication sensible), le RGPD et l'anonymisation, et la rédaction d'une charte d'usage de l'IA. Il crée aussi des assistants pour le recrutement, l'intégration et les entretiens. Résultat : du temps gagné et un cadre clair pour toute l'entreprise."}]$j$::jsonb, $j$M1$j$, $j$Fonctionnement de l'IA et bases pratiques ; enjeux éthiques, RGPD et sécurité pour définir ce que l'IA peut faire dans l'entreprise.$j$, $j$Comprendre le fonctionnement de l'IA générative, rédiger des prompts efficaces, comparer les outils (ChatGPT, Mistral, Gemini, Claude…) et adopter les bons réflexes : limites, éthique et sécurité des données.$j$),
  ('ia-012', $j${"situation": "Recrute en continu : annonces, tri des candidatures, entretiens, synthèses pour les managers ou les clients.", "difficulte": "Volume de rédaction élevé ; risque de biais et de discrimination si l'IA est mal utilisée.", "attente": "Accélérer annonces, trames d'entretien et synthèses, en gardant la décision humaine et sans biais."}$j$::jsonb, $j$[{"formation": "ia-rh", "old": "Recrutement et marque employeur.", "new": "Recrutement et marque employeur.", "argumentaire": "Le M2 lui fait construire un assistant de recrutement (annonces, trames d'entretien, synthèses) et apprend à repérer les biais et à garder la décision humaine. Le M3 ajoute des contenus de marque employeur (visuels, vidéos). Résultat : un recrutement plus rapide et plus sûr."}]$j$::jsonb, $j$M1$j$, $j$Comprendre le fonctionnement de l'IA et l'origine des biais ; bases pratiques ; éthique et non-discrimination.$j$, $j$Comprendre le fonctionnement de l'IA générative, rédiger des prompts efficaces, comparer les outils (ChatGPT, Mistral, Gemini, Claude…) et adopter les bons réflexes : limites, éthique et sécurité des données.$j$),
  ('ia-013', $j${"situation": "Gère l'administration du personnel : contrats, courriers, attestations, procédures, accueil des nouveaux.", "difficulte": "Écrits répétitifs ; données personnelles des salariés à manipuler avec précaution.", "attente": "Disposer de modèles fiables et rédiger plus vite, en protégeant les données des salariés."}$j$::jsonb, $j$[{"formation": "ia-rh", "old": "Écrits RH et protection des données personnelles.", "new": "Écrits RH et protection des données personnelles.", "argumentaire": "Modèles de courriers et de procédures RH, anonymisation des données des salariés et vérification des productions au M2, avec une bibliothèque de prompts réutilisable."}, {"formation": "ia-admin", "old": "Si son poste est surtout administratif.", "new": "Si son poste est surtout administratif.", "argumentaire": "Courriers, notes, synthèses et organisation des documents au M2, avec un assistant pour les courriers types."}]$j$::jsonb, $j$M1$j$, $j$Fonctionnement de l'IA et bases pratiques sur ses écrits ; sécurité des données personnelles des salariés.$j$, $j$Comprendre le fonctionnement de l'IA générative, rédiger des prompts efficaces, comparer les outils (ChatGPT, Mistral, Gemini, Claude…) et adopter les bons réflexes : limites, éthique et sécurité des données.$j$),
  ('ia-014', $j${"situation": "Pilote le plan de développement des compétences, l'intégration et parfois des formations internes.", "difficulte": "Recueil des besoins, plan, supports d'intégration : beaucoup de production pour peu de ressources.", "attente": "Structurer plus vite le plan et l'intégration, et produire des supports de formation internes."}$j$::jsonb, $j$[{"formation": "ia-rh", "old": "Plan de développement des compétences et intégration.", "new": "Plan de développement des compétences et intégration.", "argumentaire": "Le M2 l'aide à structurer plan de développement des compétences et parcours d'intégration, avec des assistants dédiés et une veille juridique automatisée. Le M3 produit des supports d'intégration visuels et audio."}, {"formation": "ia-form", "old": "S'il conçoit et anime aussi des formations internes.", "new": "S'il conçoit et anime aussi des formations internes.", "argumentaire": "Scénarios pédagogiques, supports, quiz et évaluations au M2."}]$j$::jsonb, $j$M1$j$, $j$Fonctionnement de l'IA et bases pratiques ; enjeux éthiques et de sécurité pour accompagner ensuite les équipes.$j$, $j$Comprendre le fonctionnement de l'IA générative, rédiger des prompts efficaces, comparer les outils (ChatGPT, Mistral, Gemini, Claude…) et adopter les bons réflexes : limites, éthique et sécurité des données.$j$),
  ('ia-015', $j${"situation": "Manage une équipe et assure lui-même les sujets RH : recrutement, entretiens annuels, communication d'équipe.", "difficulte": "Pas de formation RH ; peur de l'erreur sur les aspects juridiques ou la confidentialité.", "attente": "Être autonome et sûr de lui sur les situations RH du quotidien, avec des documents fiables."}$j$::jsonb, $j$[{"formation": "ia-rh", "old": "Situations RH réelles, sans prérequis RH.", "new": "Situations RH réelles, sans prérequis RH.", "argumentaire": "Accessible sans prérequis RH : le M2 part de situations réelles (fiches de poste, entretiens, communications) et rappelle le cadre légal, avec un assistant pour ses documents courants. Résultat : il gagne en autonomie et en assurance sur ses sujets RH."}]$j$::jsonb, $j$M1$j$, $j$Comprendre comment fonctionne l'IA, sans prérequis ; bases pratiques ; éthique et confidentialité des données des collaborateurs.$j$, $j$Comprendre le fonctionnement de l'IA générative, rédiger des prompts efficaces, comparer les outils (ChatGPT, Mistral, Gemini, Claude…) et adopter les bons réflexes : limites, éthique et sécurité des données.$j$),
  ('ia-016', $j${"situation": "En recherche d'emploi ou en reconversion, souhaite renforcer son employabilité.", "difficulte": "L'IA est désormais attendue dans de nombreux postes ; difficile de prouver cette compétence sur un CV.", "attente": "Acquérir une compétence recherchée, la mettre en pratique sur des cas professionnels et la faire reconnaître par une certification."}$j$::jsonb, $j$[{"formation": "ia-admin", "old": "S'il vise un poste administratif ou commercial.", "new": "S'il vise un poste administratif ou commercial.", "argumentaire": "Le M2 le met en situation sur des cas professionnels concrets (mails, comptes rendus, documents commerciaux, assistant personnalisé). La certification RS7232 rend la compétence visible sur son CV."}, {"formation": "ia-form", "old": "S'il se reconvertit vers la formation.", "new": "S'il se reconvertit vers la formation.", "argumentaire": "Le M2 lui apprend à concevoir des scénarios, supports et évaluations avec l'IA, un atout pour se positionner comme formateur."}]$j$::jsonb, $j$M1$j$, $j$Comprendre le fonctionnement de l'IA ; bases pratiques accessibles à tous ; usages responsables et sécurisés.$j$, $j$Comprendre le fonctionnement de l'IA générative, rédiger des prompts efficaces, comparer les outils (ChatGPT, Mistral, Gemini, Claude…) et adopter les bons réflexes : limites, éthique et sécurité des données.$j$),
  ('ia-017', $j${"situation": "Produit synthèses, courriers aux clients et procédures dans un cabinet ou un service comptable.", "difficulte": "Données financières confidentielles ; méfiance envers des outils qui peuvent se tromper sur les chiffres.", "attente": "Rédiger plus vite tout en sachant anonymiser les données et vérifier les résultats."}$j$::jsonb, $j$[{"formation": "ia-admin", "old": "Écrits de gestion et sécurisation des données chiffrées.", "new": "Écrits de gestion et sécurisation des données chiffrées.", "argumentaire": "Le M2 travaille courriers, synthèses et procédures, avec une règle centrale : anonymiser les données financières avant toute saisie et vérifier chaque chiffre. Résultat : des écrits plus rapides sans risque pour les clients."}]$j$::jsonb, $j$M1$j$, $j$Fonctionnement de l'IA et risques d'erreur sur les chiffres ; bases pratiques ; confidentialité des données financières.$j$, $j$Comprendre le fonctionnement de l'IA générative, rédiger des prompts efficaces, comparer les outils (ChatGPT, Mistral, Gemini, Claude…) et adopter les bons réflexes : limites, éthique et sécurité des données.$j$),
  ('ia-018', $j${"situation": "Rédige courriers et comptes rendus dans un cabinet médical, juridique ou libéral.", "difficulte": "Données très sensibles, secret professionnel ; aucune erreur ni fuite possible.", "attente": "Gagner du temps sur les écrits courants avec des règles strictes : rien d'identifiant dans l'outil, tout est vérifié."}$j$::jsonb, $j$[{"formation": "ia-admin", "old": "Écrits du quotidien avec une exigence forte de confidentialité.", "new": "Écrits du quotidien avec une exigence forte de confidentialité.", "argumentaire": "Le M2 construit des modèles de courriers et de comptes rendus sans données identifiantes, avec des règles de confidentialité strictes et une vérification systématique. Résultat : du temps gagné dans le respect du secret professionnel."}]$j$::jsonb, $j$M1$j$, $j$Comprendre le fonctionnement de l'IA ; bases pratiques ; secret professionnel et données qui ne doivent jamais être saisies.$j$, $j$Comprendre le fonctionnement de l'IA générative, rédiger des prompts efficaces, comparer les outils (ChatGPT, Mistral, Gemini, Claude…) et adopter les bons réflexes : limites, éthique et sécurité des données.$j$),
  ('ia-019', $j${"situation": "Gère à la fois l'administratif, les services généraux, l'accueil des salariés et la communication interne.", "difficulte": "Tâches très variées et urgentes ; difficulté à tout organiser et documenter.", "attente": "Gagner du temps sur les écrits et l'organisation, et diffuser de bonnes pratiques de l'IA en interne."}$j$::jsonb, $j$[{"formation": "ia-admin", "old": "Si sa priorité est l'administratif et l'organisation.", "new": "Si sa priorité est l'administratif et l'organisation.", "argumentaire": "Courriers, comptes rendus, suivi des dossiers et pistes d'automatisation au M2, avec un assistant personnalisé."}, {"formation": "ia-rh", "old": "S'il gère aussi l'intégration et le suivi des salariés.", "new": "S'il gère aussi l'intégration et le suivi des salariés.", "argumentaire": "Livret d'accueil, communication interne, procédures RH et charte d'usage de l'IA au M2."}]$j$::jsonb, $j$M1$j$, $j$Fonctionnement de l'IA et bases pratiques pour toutes ses tâches ; règles d'éthique et de sécurité à diffuser en interne.$j$, $j$Comprendre le fonctionnement de l'IA générative, rédiger des prompts efficaces, comparer les outils (ChatGPT, Mistral, Gemini, Claude…) et adopter les bons réflexes : limites, éthique et sécurité des données.$j$),
  ('ia-020', $j${"situation": "Établit la paie et répond aux questions des salariés : notes d'information, procédures, explications.", "difficulte": "Sujet réglementé où l'erreur coûte cher ; données personnelles et salariales très sensibles.", "attente": "Produire plus vite notes et réponses types, avec une vérification systématique et des données protégées."}$j$::jsonb, $j$[{"formation": "ia-rh", "old": "Le plus adapté : écrits RH et données personnelles.", "new": "Le plus adapté : écrits RH et données personnelles.", "argumentaire": "Notes d'information, procédures et réponses types aux salariés au M2, avec anonymisation des données et vérification systématique sur un sujet réglementé."}, {"formation": "ia-admin", "old": "Si son poste est surtout administratif et comptable.", "new": "Si son poste est surtout administratif et comptable.", "argumentaire": "Synthèses, courriers et procédures au M2."}]$j$::jsonb, $j$M1$j$, $j$Fonctionnement de l'IA et limites sur des sujets réglementés ; bases pratiques ; confidentialité des données de paie.$j$, $j$Comprendre le fonctionnement de l'IA générative, rédiger des prompts efficaces, comparer les outils (ChatGPT, Mistral, Gemini, Claude…) et adopter les bons réflexes : limites, éthique et sécurité des données.$j$),
  ('ia-021', $j${"situation": "Rédige annonces, comptes rendus de visite, relances et propositions pour vendeurs et acquéreurs.", "difficulte": "Beaucoup d'écrits commerciaux à personnaliser ; besoin de se démarquer avec des annonces attractives.", "attente": "Rédiger plus vite des annonces et un suivi client soignés, dans son propre style."}$j$::jsonb, $j$[{"formation": "ia-admin", "old": "Rédaction commerciale et suivi des clients.", "new": "Rédaction commerciale et suivi des clients.", "argumentaire": "Le M2 lui fait produire annonces attractives, comptes rendus de visite et relances, et créer un assistant qui rédige ses annonces dans son style. Le M3 ajoute visuels d'annonces et supports de présentation des biens. Résultat : plus de temps pour les visites et la négociation."}]$j$::jsonb, $j$M1$j$, $j$Comprendre le fonctionnement de l'IA ; bases pratiques ; sécurité des données des vendeurs et acquéreurs.$j$, $j$Comprendre le fonctionnement de l'IA générative, rédiger des prompts efficaces, comparer les outils (ChatGPT, Mistral, Gemini, Claude…) et adopter les bons réflexes : limites, éthique et sécurité des données.$j$),
  ('ia-022', $j${"situation": "Répond chaque jour par écrit aux demandes du public ou des clients : mails, messages, FAQ.", "difficulte": "Demandes répétitives, ton à adapter, informations à ne pas divulguer.", "attente": "Répondre plus vite, clairement et avec le bon ton, grâce à des réponses types adaptables."}$j$::jsonb, $j$[{"formation": "ia-admin", "old": "Relation client écrite au quotidien.", "new": "Relation client écrite au quotidien.", "argumentaire": "Le M2 construit des réponses types adaptables et un assistant nourri des informations de la structure, avec reformulation et vérification. Le M3 l'aide à créer fiches pratiques et affichages. Résultat : des réponses plus rapides, claires et homogènes."}]$j$::jsonb, $j$M1$j$, $j$Comment fonctionne l'IA, en termes simples ; bases pratiques ; éthique et protection des données du public.$j$, $j$Comprendre le fonctionnement de l'IA générative, rédiger des prompts efficaces, comparer les outils (ChatGPT, Mistral, Gemini, Claude…) et adopter les bons réflexes : limites, éthique et sécurité des données.$j$),
  ('ia-023', $j${"situation": "Pilote la démarche qualité (Qualiopi, ISO) : procédures, preuves, questionnaires, bilans, audits.", "difficulte": "Production documentaire lourde et à tenir à jour ; analyse des questionnaires de satisfaction chronophage.", "attente": "Rédiger et mettre à jour plus vite les documents qualité et analyser les retours, de manière fiable."}$j$::jsonb, $j$[{"formation": "ia-form", "old": "En organisme de formation : qualité et pratiques pédagogiques.", "new": "En organisme de formation : qualité et pratiques pédagogiques.", "argumentaire": "Le M2 traite questionnaires, évaluations et analyse des retours, et permet de créer un assistant qualité nourri des procédures de l'organisme, utile pour Qualiopi."}, {"formation": "ia-admin", "old": "En entreprise : procédures et documents qualité.", "new": "En entreprise : procédures et documents qualité.", "argumentaire": "Rédaction et mise à jour des procédures, synthèses et comptes rendus d'audit au M2, avec un assistant dédié."}]$j$::jsonb, $j$M1$j$, $j$Fonctionnement de l'IA et bases pratiques ; enjeux éthiques et de sécurité pour encadrer son usage dans l'organisme.$j$, $j$Comprendre le fonctionnement de l'IA générative, rédiger des prompts efficaces, comparer les outils (ChatGPT, Mistral, Gemini, Claude…) et adopter les bons réflexes : limites, éthique et sécurité des données.$j$),
  ('ia-024', $j${"situation": "Accompagne des publics en insertion, orientation ou bilan : entretiens, synthèses, ateliers collectifs.", "difficulte": "Temps de rédaction important ; données personnelles des bénéficiaires ; risque de biais dans les synthèses.", "attente": "Préparer plus vite ateliers et synthèses, et aider les bénéficiaires à utiliser l'IA pour leurs CV et lettres."}$j$::jsonb, $j$[{"formation": "ia-form", "old": "Ateliers collectifs et accompagnement.", "new": "Ateliers collectifs et accompagnement.", "argumentaire": "Le M2 aide à concevoir supports d'atelier et outils d'auto-positionnement avec l'IA, et à en parler aux bénéficiaires."}, {"formation": "ia-rh", "old": "Bilans, projets professionnels et recherche d'emploi.", "new": "Bilans, projets professionnels et recherche d'emploi.", "argumentaire": "Synthèses, CV et lettres travaillés avec les bénéficiaires au M2, en repérant les biais et en protégeant leurs données."}]$j$::jsonb, $j$M1$j$, $j$Fonctionnement de l'IA et bases pratiques ; éthique, biais et protection des données des bénéficiaires.$j$, $j$Comprendre le fonctionnement de l'IA générative, rédiger des prompts efficaces, comparer les outils (ChatGPT, Mistral, Gemini, Claude…) et adopter les bons réflexes : limites, éthique et sécurité des données.$j$),
  ('ia-025', $j${"situation": "Tient un commerce ou un restaurant et gère seul(e) l'affichage, les menus, les mails et les avis en ligne.", "difficulte": "Peu de temps en dehors du service ; avis clients à traiter ; communication souvent laissée de côté.", "attente": "Gagner du temps sur la relation client et la communication, avec des modèles réutilisables."}$j$::jsonb, $j$[{"formation": "ia-admin", "old": "Gestion et relation client au quotidien.", "new": "Gestion et relation client au quotidien.", "argumentaire": "Le M2 couvre son quotidien : réponses aux avis, mails clients, fiches produits, avec un assistant pour répondre aux clients. Le M3 lui fait créer visuels de menus, d'offres et d'affichages. Résultat : une communication régulière sans y passer ses soirées."}]$j$::jsonb, $j$M1$j$, $j$Comprendre ce qu'est l'IA et comment elle fonctionne ; bases pratiques ; bons réflexes de sécurité.$j$, $j$Comprendre le fonctionnement de l'IA générative, rédiger des prompts efficaces, comparer les outils (ChatGPT, Mistral, Gemini, Claude…) et adopter les bons réflexes : limites, éthique et sécurité des données.$j$),
  ('pao-001', $j${"situation": "Produit en interne plaquettes, affiches, visuels et photos pour la communication de la structure.", "difficulte": "Outils mal maîtrisés, dépendance à un prestataire, rendu pas toujours professionnel.", "attente": "Maîtriser les logiciels de référence pour produire soi-même des supports prêts à imprimer ou à publier."}$j$::jsonb, $j$[{"formation": "pao-indesign", "old": "Le plus adapté pour ses plaquettes, affiches et documents imprimés.", "new": "Le plus adapté pour ses plaquettes, affiches et documents imprimés.", "argumentaire": "Mise en page professionnelle prête à imprimer, avec certification Tosa."}, {"formation": "pao-photoshop-init", "old": "Pour retoucher et composer ses images.", "new": "À proposer pour retoucher et composer ses images pour tous ses supports.", "argumentaire": ""}, {"formation": "pao-illustrator", "old": "Pour créer logos, pictogrammes et illustrations.", "new": "À proposer pour créer logos, pictogrammes et illustrations vectorielles nets à toutes les tailles.", "argumentaire": ""}]$j$::jsonb, null, null, null),
  ('pao-002', $j${"situation": "Photographe ou vidéaste indépendant(e) qui veut monter en gamme.", "difficulte": "Rendu irrégulier, temps de post-production long, retouches avancées mal maîtrisées.", "attente": "Des prises de vue maîtrisées et une post-production efficace, à un niveau professionnel."}$j$::jsonb, $j$[{"formation": "pao-prise-vue", "old": "Pour maîtriser exposition, lumière et cadrage.", "new": "À proposer pour maîtriser exposition, lumière et cadrage, en photo comme en vidéo.", "argumentaire": ""}, {"formation": "pao-lightroom", "old": "Pour trier et développer ses séries de photos.", "new": "À proposer pour trier son catalogue et développer ses séries de photos de façon homogène.", "argumentaire": ""}, {"formation": "pao-photoshop-perf", "old": "Pour les retouches avancées.", "new": "Pour les retouches avancées.", "argumentaire": "Retouches fines, montages et compositions."}]$j$::jsonb, null, null, null),
  ('pao-003', $j${"situation": "Commerçant(e), artisan ou e-commerçant(e) qui photographie lui-même ses produits.", "difficulte": "Photos peu valorisantes, pas de budget logiciel ni de photographe.", "attente": "De belles photos produits et des visuels qui font vendre, avec des outils accessibles."}$j$::jsonb, $j$[{"formation": "pao-prise-vue", "old": "Le plus adapté : réussir ses photos de produits.", "new": "Le plus adapté : réussir ses photos de produits.", "argumentaire": "Il apprend à photographier ses produits et réalisations avec un rendu professionnel (lumière, cadrage, exposition). Résultat : des photos qui font vendre."}, {"formation": "pao-lightroom", "old": "Pour retoucher rapidement ses photos.", "new": "À proposer pour retoucher rapidement et de façon cohérente toute une série de photos produits.", "argumentaire": ""}, {"formation": "pao-affinity", "old": "Pour un logiciel complet et gratuit.", "new": "Pour un logiciel complet et gratuit.", "argumentaire": "Retouche, visuels et mise en page."}]$j$::jsonb, null, null, null),
  ('pao-004', $j${"situation": "En reconversion vers le graphisme ou l'infographie.", "difficulte": "Les employeurs attendent la maîtrise des logiciels Adobe ; difficile de le prouver sans diplôme du métier.", "attente": "Maîtriser les logiciels de référence et les faire reconnaître par une certification."}$j$::jsonb, $j$[{"formation": "pao-photoshop-init", "old": "La base du métier : la retouche d’image.", "new": "La base du métier : la retouche d’image.", "argumentaire": "La base du métier : retouches et compositions d'images, avec une certification Tosa reconnue par les employeurs."}, {"formation": "pao-illustrator", "old": "Pour la création graphique vectorielle.", "new": "Pour la création graphique vectorielle.", "argumentaire": "Pour la création graphique vectorielle : logos, illustrations et graphiques, avec certification Tosa."}, {"formation": "pao-indesign", "old": "Pour la mise en page professionnelle.", "new": "Pour la mise en page professionnelle.", "argumentaire": "Pour la mise en page professionnelle de documents imprimés et numériques, avec certification Tosa."}]$j$::jsonb, null, null, null),
  ('pao-005', $j${"situation": "Association ou petite structure qui produit ses propres supports.", "difficulte": "Pas de budget pour des abonnements logiciels ni pour un graphiste.", "attente": "Créer affiches, flyers et visuels avec un logiciel complet et gratuit."}$j$::jsonb, $j$[{"formation": "pao-affinity", "old": "Le plus adapté : un logiciel gratuit et complet.", "new": "Le plus adapté : un logiciel gratuit et complet.", "argumentaire": "Affinity, logiciel gratuit et complet, couvre retouche photo, illustration et mise en page. Résultat : des supports professionnels sans abonnement."}, {"formation": "pao-prise-vue", "old": "Pour de meilleures photos de ses événements.", "new": "À proposer pour réussir les photos et vidéos de ses événements.", "argumentaire": ""}]$j$::jsonb, null, null, null),
  ('paoia-001', $j${"situation": "Graphiste ou maquettiste qui travaille au quotidien avec Photoshop, Illustrator et la suite Adobe.", "difficulte": "Délais serrés ; découvre les fonctions IA d'Adobe sans savoir bien les utiliser.", "attente": "Gagner du temps grâce à l'IA intégrée à ses logiciels, sans changer d'outils."}$j$::jsonb, $j$[{"formation": "paoia-adobe", "old": "Le plus adapté : l’IA intégrée à ses logiciels Adobe.", "new": "Le plus adapté : l’IA intégrée à ses logiciels Adobe.", "argumentaire": "Il apprend à utiliser les fonctions IA de Photoshop, Illustrator et de la suite Adobe (remplissage génératif, Firefly…) dans son travail habituel. Résultat : du temps gagné sans changer d'outils."}, {"formation": "paoia-design", "old": "Pour explorer les générateurs d’images IA.", "new": "À proposer pour explorer les générateurs d'images IA (Midjourney, Ideogram) et trouver de nouvelles pistes créatives.", "argumentaire": ""}]$j$::jsonb, null, null, null),
  ('paoia-002', $j${"situation": "Produit visuels de campagne et contenus pour les réseaux sociaux.", "difficulte": "Besoin de beaucoup de visuels, vite, sans graphiste dédié.", "attente": "Créer plus de visuels percutants et originaux grâce à l'IA."}$j$::jsonb, $j$[{"formation": "paoia-design", "old": "Le plus adapté : créer des visuels avec l’IA.", "new": "Le plus adapté : créer des visuels avec l’IA.", "argumentaire": "Créer visuels de campagne et de réseaux sociaux avec Midjourney et Ideogram. Résultat : plus de visuels, plus vite."}, {"formation": "paoia-adobe", "old": "S’il travaille déjà avec la suite Adobe.", "new": "S’il travaille déjà avec la suite Adobe.", "argumentaire": "Accélérer ses créations grâce à l'IA intégrée."}]$j$::jsonb, null, null, null),
  ('paoia-003', $j${"situation": "Créateur(trice) de contenu ou auto-entrepreneur créatif.", "difficulte": "Besoin de visuels originaux pour se démarquer, sans budget graphiste.", "attente": "Produire des visuels uniques avec les générateurs d'images IA."}$j$::jsonb, $j$[{"formation": "paoia-design", "old": "Le plus adapté : visuels originaux avec l’IA.", "new": "Le plus adapté : visuels originaux avec l’IA.", "argumentaire": "Il apprend à créer des visuels uniques pour ses contenus avec les générateurs d'images IA, sans graphiste."}]$j$::jsonb, null, null, null),
  ('ped-001', $j${"situation": "Formateur(trice) indépendant(e) qui conçoit ses propres modules.", "difficulte": "Supports classiques peu engageants ; difficile de se démarquer face à la concurrence.", "attente": "Créer des modules interactifs qui valorisent son offre et engagent les apprenants."}$j$::jsonb, $j$[{"formation": "ped-genially", "old": "Le plus adapté : contenus interactifs.", "new": "Le plus adapté : contenus interactifs.", "argumentaire": "Scénariser et produire des modules interactifs avec Genially. Résultat : une offre qui se démarque et des apprenants plus impliqués."}]$j$::jsonb, null, null, null),
  ('ped-002', $j${"situation": "Formateur(trice) interne ou responsable formation, de plus en plus en distanciel.", "difficulte": "Contenus à distance peu engageants ; pas d'outil auteur maîtrisé.", "attente": "Produire des modules e-learning, quiz et parcours interactifs pour la formation interne."}$j$::jsonb, $j$[{"formation": "ped-genially", "old": "Le plus adapté : modules e-learning internes.", "new": "Le plus adapté : modules e-learning internes.", "argumentaire": "Modules e-learning, quiz et parcours interactifs pour la formation interne, faciles à diffuser à distance."}]$j$::jsonb, null, null, null),
  ('ped-003', $j${"situation": "Enseignant(e) qui veut renouveler ses supports de cours.", "difficulte": "Élèves peu impliqués face à des supports statiques.", "attente": "Créer des cours, jeux et quiz interactifs qui captent l'attention."}$j$::jsonb, $j$[{"formation": "ped-genially", "old": "Le plus adapté : cours et quiz interactifs.", "new": "Le plus adapté : cours et quiz interactifs.", "argumentaire": "Supports de cours, jeux et quiz interactifs, y compris des escape games pédagogiques."}]$j$::jsonb, null, null, null),
  ('ped-004', $j${"situation": "Chargé(e) de communication qui produit présentations et contenus pour le web ou l'interne.", "difficulte": "Contenus statiques qui retiennent peu l'attention.", "attente": "Créer présentations, infographies et contenus interactifs et engageants."}$j$::jsonb, $j$[{"formation": "ped-genially", "old": "Pour des contenus qui captent l’attention.", "new": "Pour des contenus qui captent l’attention.", "argumentaire": "Pour des présentations, infographies et contenus interactifs qui captent l'attention."}]$j$::jsonb, null, null, null),
  ('prj-001', $j${"situation": "Pilote un ou plusieurs projets : planning, ressources, suivi d'avancement.", "difficulte": "Planning tenu sur Excel ou à la main, difficile à mettre à jour ; retards repérés trop tard.", "attente": "Planifier, suivre et piloter ses projets avec une méthode et un outil adaptés."}$j$::jsonb, $j$[{"formation": "prj-msproject", "old": "Le plus adapté pour un planning détaillé.", "new": "Le plus adapté pour un planning détaillé.", "argumentaire": "Tâches, dépendances, ressources et suivi d'avancement dans MS Project. Résultat : les retards se voient tout de suite."}, {"formation": "prj-agilite", "old": "Pour des projets qui évoluent souvent.", "new": "Pour des projets qui évoluent souvent.", "argumentaire": "Méthodes agiles et outils collaboratifs en ligne."}]$j$::jsonb, null, null, null),
  ('prj-002', $j${"situation": "Manage une équipe et répartit le travail au quotidien.", "difficulte": "Priorités qui changent, manque de visibilité sur qui fait quoi, réunions peu efficaces.", "attente": "Organiser le travail de l'équipe et suivre les priorités avec des méthodes simples et partagées."}$j$::jsonb, $j$[{"formation": "prj-agilite", "old": "Le plus adapté : piloter en équipe.", "new": "Le plus adapté : piloter en équipe.", "argumentaire": "Rituels d'équipe, tableaux de suivi (Kanban, Trello) et priorisation avec les méthodes agiles. Résultat : une équipe qui sait quoi faire et dans quel ordre."}]$j$::jsonb, null, null, null),
  ('prj-003', $j${"situation": "Coordonne un chantier ou une production avec plusieurs intervenants.", "difficulte": "Délais serrés, dépendances entre tâches, ressources à répartir.", "attente": "Construire et suivre un planning fiable pour tenir les délais et coordonner les équipes."}$j$::jsonb, $j$[{"formation": "prj-msproject", "old": "Le plus adapté : planning et ressources.", "new": "Le plus adapté : planning et ressources.", "argumentaire": "Construire un planning de chantier ou de production, gérer les dépendances et les ressources, suivre l'avancement. Résultat : des délais mieux tenus."}]$j$::jsonb, null, null, null),
  ('prj-004', $j${"situation": "Mène des projets avec des partenaires multiples (association, collectivité).", "difficulte": "Acteurs nombreux, informations dispersées, projets qui évoluent en cours de route.", "attente": "Organiser et piloter des projets partagés avec des méthodes souples et des outils en ligne."}$j$::jsonb, $j$[{"formation": "prj-agilite", "old": "Le plus adapté : projets partagés et évolutifs.", "new": "Le plus adapté : projets partagés et évolutifs.", "argumentaire": "Méthodes souples et outils en ligne pour organiser des projets partenariaux qui évoluent."}]$j$::jsonb, null, null, null),
  ('rs-001', $j${"situation": "Vient de créer son activité et doit se faire connaître.", "difficulte": "Peu de temps, pas de budget agence, ne sait pas sur quels réseaux aller ni quoi publier.", "attente": "Être présent sur les bons réseaux et publier régulièrement pour trouver ses premiers clients."}$j$::jsonb, $j$[{"formation": "rs-simple", "old": "L'essentiel en 3 jours pour être présent et publier régulièrement.", "new": "L'essentiel en 3 jours pour être présent et publier régulièrement.", "argumentaire": "L'essentiel en 3 jours : choisir les réseaux de sa cible et créer une page pro complète (M1), puis un rythme de publication tenable avec des formats simples (M2.1). Résultat : une présence active dès la fin de la formation."}, {"formation": "rs-marque", "old": "S'il n'a pas encore de logo ni de positionnement clair.", "new": "S'il n'a pas encore de logo ni de positionnement clair.", "argumentaire": "Le M1 Socle définit positionnement et charte graphique avant de publier."}, {"formation": "rs-local", "old": "Si ses clients sont dans sa ville ou sa zone d'intervention.", "new": "Si ses clients sont dans sa ville ou sa zone d'intervention.", "argumentaire": "Le M2.3 crée sa fiche Google Business Profile pour être trouvé près de chez lui."}, {"formation": "rs-video", "old": "S'il veut se montrer en vidéo pour créer la confiance.", "new": "S'il veut se montrer en vidéo pour créer la confiance.", "argumentaire": "Le M3 apprend à filmer et monter seul sur smartphone."}]$j$::jsonb, $j$M1 Base$j$, $j$Choisir les réseaux de sa cible et créer une page pro complète pendant la formation.$j$, $j$Choisir les réseaux adaptés à sa cible et créer ou optimiser une page professionnelle complète.$j$),
  ('rs-002', $j${"situation": "Créateur(trice) ou artisan d'art qui vend en direct, sur des marchés ou en ligne.", "difficulte": "Ses créations sont belles mais peu visibles ; publications irrégulières.", "attente": "Montrer son travail et son univers pour vendre davantage."}$j$::jsonb, $j$[{"formation": "rs-video", "old": "Pour montrer le geste et les coulisses de fabrication.", "new": "Pour montrer le geste et les coulisses de fabrication.", "argumentaire": "Vidéos tournées et montées au smartphone (M3), en plus des bases et de la stratégie de publication."}, {"formation": "rs-marque", "old": "Pour un univers de marque reconnaissable.", "new": "Pour un univers de marque reconnaissable.", "argumentaire": "Charte et univers visuel qui reflètent son style (M1 Socle)."}, {"formation": "rs-simple", "old": "S'il a déjà une identité et veut surtout mieux publier.", "new": "S'il a déjà une identité et veut surtout mieux publier.", "argumentaire": "L'essentiel en 3 jours."}]$j$::jsonb, $j$M1 Base$j$, $j$Page pro qui met en valeur ses créations.$j$, $j$Choisir les réseaux adaptés à sa cible et créer ou optimiser une page professionnelle complète.$j$),
  ('rs-003', $j${"situation": "Consultant(e) ou freelance qui vend ses services à des entreprises.", "difficulte": "Dépend du bouche-à-oreille ; profil peu visible auprès des décideurs.", "attente": "Trouver des clients professionnels et asseoir son expertise, surtout sur LinkedIn."}$j$::jsonb, $j$[{"formation": "rs-linkedin", "old": "Le canal principal pour trouver des clients professionnels.", "new": "Le canal principal pour trouver des clients professionnels.", "argumentaire": "Le canal principal pour trouver des clients professionnels : profil optimisé, publications d'expertise et réseau ciblé (M2.2), avec une stratégie de contenu (M2.1). Résultat : des contacts qualifiés."}, {"formation": "rs-marque", "old": "S'il doit d'abord clarifier son positionnement et son image.", "new": "À proposer s'il doit d'abord clarifier son positionnement et son image d'expert (M1 Socle).", "argumentaire": ""}]$j$::jsonb, $j$M1 Base$j$, $j$Identifier sa cible professionnelle et soigner sa présence.$j$, $j$Choisir les réseaux adaptés à sa cible et créer ou optimiser une page professionnelle complète.$j$),
  ('rs-004', $j${"situation": "Praticien(ne), coach ou enseignant(e) indépendant(e) : bien-être, cours, accompagnement.", "difficulte": "Activité de confiance : les futurs clients veulent être rassurés avant de réserver.", "attente": "Être trouvé localement et inspirer confiance avant le premier rendez-vous."}$j$::jsonb, $j$[{"formation": "rs-local", "old": "Si sa clientèle vient de sa ville.", "new": "Si sa clientèle vient de sa ville.", "argumentaire": "Être trouvé sur Google et valoriser ses avis clients (M2.3)."}, {"formation": "rs-video", "old": "Pour se présenter en vidéo avant le premier rendez-vous.", "new": "Pour se présenter en vidéo avant le premier rendez-vous.", "argumentaire": "Vidéos de présentation et de conseils au smartphone (M3)."}, {"formation": "rs-linkedin", "old": "S'il accompagne aussi des entreprises ou des salariés.", "new": "S'il accompagne aussi des entreprises ou des salariés.", "argumentaire": "Présence LinkedIn (M2.2)."}]$j$::jsonb, $j$M1 Base$j$, $j$Page pro claire sur l'offre et la prise de rendez-vous.$j$, $j$Choisir les réseaux adaptés à sa cible et créer ou optimiser une page professionnelle complète.$j$),
  ('rs-005', $j${"situation": "Lance son entreprise ou sa marque.", "difficulte": "Pas encore de logo, de charte ni de positionnement clair ; risque de communiquer sans cohérence.", "attente": "Définir son identité de marque avant de se lancer sur les réseaux."}$j$::jsonb, $j$[{"formation": "rs-marque", "old": "Le plus adapté : l'identité de marque d'abord.", "new": "Le plus adapté : l'identité de marque d'abord.", "argumentaire": "L'identité d'abord. Le M1 Socle construit positionnement et charte graphique, puis il crée ses pages pro aux couleurs de la marque et publie avec cohérence. Résultat : une marque lancée sur de bonnes bases."}, {"formation": "rs-simple", "old": "Si son identité est déjà définie (logo, charte).", "new": "Si son identité est déjà définie (logo, charte).", "argumentaire": "L'essentiel en 3 jours pour publier."}]$j$::jsonb, $j$M1 Base$j$, $j$Pages pro créées dès le départ aux couleurs de la marque.$j$, $j$Choisir les réseaux adaptés à sa cible et créer ou optimiser une page professionnelle complète.$j$),
  ('rs-006', $j${"situation": "Restaurateur, hébergeur ou acteur touristique.", "difficulte": "Les clients choisissent sur Google et Instagram ; avis à gérer ; saisonnalité.", "attente": "Être trouvé et choisi par les habitants et les visiteurs, et remplir son établissement."}$j$::jsonb, $j$[{"formation": "rs-local", "old": "Pour être choisi sur Google par les visiteurs et les habitants.", "new": "Pour être choisi sur Google par les visiteurs et les habitants.", "argumentaire": "Fiche Google optimisée et gestion des avis (M2.3), réseaux adaptés à ses clientèles locale et touristique, publications qui donnent envie (M2.1). Résultat : plus de réservations."}, {"formation": "rs-video", "old": "Pour donner envie avec des vidéos du lieu et de l'expérience.", "new": "À proposer pour donner envie avec des vidéos du lieu, des plats ou des activités, tournées au smartphone (M3).", "argumentaire": ""}, {"formation": "rs-marque", "old": "Pour un établissement en création ou à l'identité à affirmer.", "new": "À proposer pour un établissement en création ou dont l'identité est à affirmer (M1 Socle).", "argumentaire": ""}]$j$::jsonb, $j$M1 Base$j$, $j$Réseaux adaptés à ses clientèles locale et touristique.$j$, $j$Choisir les réseaux adaptés à sa cible et créer ou optimiser une page professionnelle complète.$j$),
  ('rs-007', $j${"situation": "Tient une boutique, un salon ou une épicerie de quartier.", "difficulte": "Concurrence des grandes enseignes et du web ; fiche Google incomplète ou absente.", "attente": "Attirer la clientèle du quartier et être trouvé sur Google."}$j$::jsonb, $j$[{"formation": "rs-local", "old": "Le plus adapté : la visibilité de proximité.", "new": "Le plus adapté : la visibilité de proximité.", "argumentaire": "Fiche Google Business Profile complète (horaires, photos, avis) au M2.3, et des publications sur nouveautés, promotions et événements. Résultat : plus de clients du quartier."}, {"formation": "rs-video", "old": "Pour animer sa vitrine en ligne avec des vidéos.", "new": "À proposer pour animer sa vitrine en ligne avec des vidéos des produits et de la boutique (M3).", "argumentaire": ""}, {"formation": "rs-simple", "old": "S'il a peu de temps et veut l'essentiel en 3 jours.", "new": "À proposer s'il a peu de temps et veut l'essentiel en 3 jours.", "argumentaire": ""}]$j$::jsonb, $j$M1 Base$j$, $j$Pages pro tournées vers la clientèle locale.$j$, $j$Choisir les réseaux adaptés à sa cible et créer ou optimiser une page professionnelle complète.$j$),
  ('rs-008', $j${"situation": "Artisan ou auto-entrepreneur du bâtiment ou des services à domicile.", "difficulte": "Les clients cherchent « près de chez moi » ; avis et réalisations peu mis en avant.", "attente": "Être trouvé dans sa zone d'intervention et rassurer avec ses réalisations et ses avis."}$j$::jsonb, $j$[{"formation": "rs-local", "old": "Le plus adapté : ses clients cherchent un artisan près de chez eux.", "new": "Le plus adapté : ses clients cherchent un artisan près de chez eux.", "argumentaire": "Ses clients cherchent un artisan près de chez eux. Visibilité sur Google Maps et gestion des avis (M2.3), avant/après et chantiers publiés régulièrement (M2.1). Résultat : plus de demandes de devis."}, {"formation": "rs-video", "old": "Pour montrer son savoir-faire en vidéo.", "new": "À proposer pour montrer son savoir-faire avec des vidéos de chantiers et de réalisations (M3).", "argumentaire": ""}, {"formation": "rs-simple", "old": "S'il veut l'essentiel en 3 jours.", "new": "À proposer s'il veut l'essentiel en 3 jours.", "argumentaire": ""}]$j$::jsonb, $j$M1 Base$j$, $j$Page pro qui montre ses réalisations.$j$, $j$Choisir les réseaux adaptés à sa cible et créer ou optimiser une page professionnelle complète.$j$),
  ('rs-009', $j${"situation": "Gère une boutique en ligne.", "difficulte": "Forte concurrence, trafic insuffisant, marque peu reconnaissable.", "attente": "Se démarquer et amener du trafic qualifié vers sa boutique."}$j$::jsonb, $j$[{"formation": "rs-marque", "old": "Pour une marque reconnaissable face à la concurrence en ligne.", "new": "Pour une marque reconnaissable face à la concurrence en ligne.", "argumentaire": "Identité et univers visuel des produits (M1 Socle), reliés à la boutique."}, {"formation": "rs-video", "old": "Pour présenter ses produits en vidéo.", "new": "À proposer pour présenter ses produits en vidéos courtes, tournées et montées au smartphone (M3).", "argumentaire": ""}]$j$::jsonb, $j$M1 Base$j$, $j$Réseaux adaptés à sa clientèle et pages reliées à la boutique.$j$, $j$Choisir les réseaux adaptés à sa cible et créer ou optimiser une page professionnelle complète.$j$),
  ('rs-010', $j${"situation": "Artisan ou TPE déjà présent sur les réseaux.", "difficulte": "Publie au coup par coup, sans stratégie ni régularité ; peu de résultats.", "attente": "Passer à une présence suivie et efficace, avec un planning tenable."}$j$::jsonb, $j$[{"formation": "rs-simple", "old": "Pour structurer sa présence en 3 jours.", "new": "Pour structurer sa présence en 3 jours.", "argumentaire": "Bases communes (M1), puis planning éditorial et lecture des statistiques (M2.1). Résultat : une présence régulière et mesurable."}, {"formation": "rs-local", "old": "Si sa clientèle est locale.", "new": "Si sa clientèle est locale.", "argumentaire": "Fiche Google à jour pour compléter les réseaux (M2.3)."}, {"formation": "rs-video", "old": "Pour publier des vidéos qui retiennent l'attention.", "new": "À proposer pour publier des vidéos courtes qui retiennent l'attention (M3).", "argumentaire": ""}]$j$::jsonb, $j$M1 Base$j$, $j$Audit de la page existante et corrections prioritaires.$j$, $j$Choisir les réseaux adaptés à sa cible et créer ou optimiser une page professionnelle complète.$j$),
  ('rs-011', $j${"situation": "Salarié(e) à qui l'entreprise confie les réseaux sociaux, en plus de son poste.", "difficulte": "Pas de formation en communication ; ne sait pas par où commencer ni comment mesurer les résultats.", "attente": "Prendre en charge les réseaux de l'entreprise avec une méthode claire."}$j$::jsonb, $j$[{"formation": "rs-simple", "old": "L'essentiel pour démarrer en 3 jours.", "new": "L'essentiel pour démarrer en 3 jours.", "argumentaire": "L'essentiel pour démarrer en 3 jours : cible, plateformes et page professionnelle (M1), puis une méthode pour proposer et tenir une stratégie de publication (M2.1)."}, {"formation": "rs-video", "old": "Si l'entreprise attend aussi des vidéos.", "new": "Si l'entreprise attend aussi des vidéos.", "argumentaire": "Production autonome au smartphone (M3)."}, {"formation": "rs-linkedin", "old": "Si l'entreprise travaille surtout avec des professionnels.", "new": "Si l'entreprise travaille surtout avec des professionnels.", "argumentaire": "Animer la page LinkedIn (M2.2)."}]$j$::jsonb, $j$M1 Base$j$, $j$Bases solides : cible, plateformes, page professionnelle.$j$, $j$Choisir les réseaux adaptés à sa cible et créer ou optimiser une page professionnelle complète.$j$),
  ('rs-012', $j${"situation": "Responsable communication ou marketing en TPE-PME ou collectivité.", "difficulte": "Image peu homogène d'une plateforme à l'autre ; contenus, surtout vidéo, sous-traités ou absents.", "attente": "Harmoniser l'image et produire des contenus en interne."}$j$::jsonb, $j$[{"formation": "rs-marque", "old": "Pour harmoniser l'image sur toutes les plateformes.", "new": "Pour harmoniser l'image sur toutes les plateformes.", "argumentaire": "Charte graphique de référence (M1 Socle) et audit de la présence existante."}, {"formation": "rs-video", "old": "Pour produire des vidéos en interne.", "new": "Pour produire des vidéos en interne.", "argumentaire": "Prise de vue, son et montage sur smartphone (M3)."}, {"formation": "rs-linkedin", "old": "Pour la communication B2B et institutionnelle.", "new": "Pour la communication B2B et institutionnelle.", "argumentaire": "Page entreprise et contenus LinkedIn (M2.2)."}]$j$::jsonb, $j$M1 Base$j$, $j$Audit de la présence existante, plateforme par plateforme.$j$, $j$Choisir les réseaux adaptés à sa cible et créer ou optimiser une page professionnelle complète.$j$),
  ('rs-013', $j${"situation": "Dirige une TPE ou une PME.", "difficulte": "Peu visible personnellement, alors que clients et partenaires regardent qui dirige l'entreprise.", "attente": "Incarner son entreprise et gagner en crédibilité auprès des professionnels."}$j$::jsonb, $j$[{"formation": "rs-linkedin", "old": "Pour sa réputation auprès des clients et partenaires professionnels.", "new": "Pour sa réputation auprès des clients et partenaires professionnels.", "argumentaire": "Prise de parole du dirigeant et développement de son réseau sur LinkedIn (M2.2), en lien avec la page de l'entreprise."}, {"formation": "rs-marque", "old": "Si l'image de l'entreprise est à revoir.", "new": "Si l'image de l'entreprise est à revoir.", "argumentaire": "Positionnement et identité (M1 Socle)."}]$j$::jsonb, $j$M1 Base$j$, $j$Articuler page entreprise et présence du dirigeant.$j$, $j$Choisir les réseaux adaptés à sa cible et créer ou optimiser une page professionnelle complète.$j$),
  ('rs-014', $j${"situation": "Commercial(e) B2B ou business developer.", "difficulte": "La prospection classique s'essouffle ; ses clients sont sur LinkedIn.", "attente": "Prospecter et entretenir sa relation client sur les réseaux (social selling)."}$j$::jsonb, $j$[{"formation": "rs-linkedin", "old": "Le canal de la prospection B2B.", "new": "Le canal de la prospection B2B.", "argumentaire": "Le canal de la prospection B2B : cibler les bons interlocuteurs, développer et animer son réseau, publier des contenus qui ouvrent la conversation (M2.2). Résultat : plus de rendez-vous qualifiés."}]$j$::jsonb, $j$M1 Base$j$, $j$Cibler les bons interlocuteurs.$j$, $j$Choisir les réseaux adaptés à sa cible et créer ou optimiser une page professionnelle complète.$j$),
  ('rs-015', $j${"situation": "Travaille aux RH ou au recrutement.", "difficulte": "Difficultés à recruter ; marque employeur peu visible.", "attente": "Valoriser l'entreprise comme employeur et attirer des candidats."}$j$::jsonb, $j$[{"formation": "rs-linkedin", "old": "Le réseau des candidats et des recruteurs.", "new": "Le réseau des candidats et des recruteurs.", "argumentaire": "Le réseau des candidats : diffuser les offres, développer son vivier et publier régulièrement des contenus de marque employeur (M2.2)."}, {"formation": "rs-video", "old": "Pour des vidéos métiers et des témoignages de salariés.", "new": "À proposer pour des vidéos métiers et des témoignages de salariés tournés au smartphone (M3).", "argumentaire": ""}]$j$::jsonb, $j$M1 Base$j$, $j$Présence pensée pour les candidats.$j$, $j$Choisir les réseaux adaptés à sa cible et créer ou optimiser une page professionnelle complète.$j$),
  ('rs-016', $j${"situation": "Salarié(e) ou bénévole d'association.", "difficulte": "Peu de moyens ; actions et événements peu connus du public.", "attente": "Faire connaître les actions et mobiliser adhérents, bénévoles et donateurs."}$j$::jsonb, $j$[{"formation": "rs-simple", "old": "L'essentiel en 3 jours, avec peu de moyens.", "new": "L'essentiel en 3 jours, avec peu de moyens.", "argumentaire": "L'essentiel en 3 jours, avec peu de moyens : une page claire pour adhérents et partenaires, et des publications qui annoncent et valorisent les événements."}, {"formation": "rs-video", "old": "Pour raconter les actions en vidéo.", "new": "Pour raconter les actions en vidéo.", "argumentaire": "Événements et témoignages au smartphone (M3)."}]$j$::jsonb, $j$M1 Base$j$, $j$Page claire, adaptée aux adhérents et partenaires.$j$, $j$Choisir les réseaux adaptés à sa cible et créer ou optimiser une page professionnelle complète.$j$),
  ('rs-017', $j${"situation": "Salarié(e) en évolution ou demandeur d'emploi en transition professionnelle.", "difficulte": "Profil peu visible des recruteurs ; réseau professionnel limité.", "attente": "Être repéré par les recruteurs et valoriser son parcours."}$j$::jsonb, $j$[{"formation": "rs-linkedin", "old": "Le plus adapté pour une recherche d'emploi ou une évolution.", "new": "Le plus adapté pour une recherche d'emploi ou une évolution.", "argumentaire": "Profil optimisé, réseau développé vers son projet et contenus qui montrent ses compétences (M2.2)."}, {"formation": "rs-simple", "old": "S'il vise un métier où il gérera des réseaux sociaux.", "new": "À proposer s'il vise un métier où il gérera des réseaux sociaux.", "argumentaire": ""}]$j$::jsonb, $j$M1 Base$j$, $j$Définir sa cible : secteurs, entreprises, recruteurs.$j$, $j$Choisir les réseaux adaptés à sa cible et créer ou optimiser une page professionnelle complète.$j$),
  ('rs-018', $j${"situation": "Agent immobilier ou mandataire indépendant.", "difficulte": "Forte concurrence locale ; besoin d'être reconnu comme la référence de son secteur.", "attente": "Mettre en avant ses biens et sa notoriété locale pour décrocher des mandats."}$j$::jsonb, $j$[{"formation": "rs-local", "old": "Le plus adapté : être la référence de son secteur.", "new": "Le plus adapté : être la référence de son secteur.", "argumentaire": "Devenir la référence de son secteur avec une fiche Google, des avis clients et une visibilité dans les recherches locales (M2.3), et des publications de biens et de ventes réalisées."}, {"formation": "rs-video", "old": "Pour des visites vidéo des biens.", "new": "À proposer pour des visites et présentations de biens filmées et montées au smartphone (M3).", "argumentaire": ""}, {"formation": "rs-linkedin", "old": "Pour travailler avec des professionnels et investisseurs.", "new": "Pour travailler avec des professionnels et investisseurs.", "argumentaire": "Réseau d'apporteurs d'affaires sur LinkedIn (M2.2)."}]$j$::jsonb, $j$M1 Base$j$, $j$Choisir les réseaux de ses acheteurs et vendeurs, page pro complète.$j$, $j$Choisir les réseaux adaptés à sa cible et créer ou optimiser une page professionnelle complète.$j$),
  ('rs-019', $j${"situation": "Agriculteur ou producteur en vente directe.", "difficulte": "Clients locaux à informer (ventes, marchés, horaires) ; peu de temps pour communiquer.", "attente": "Faire connaître sa ferme, ses produits et ses points de vente."}$j$::jsonb, $j$[{"formation": "rs-local", "old": "Le plus adapté : ses clients sont autour de chez lui.", "new": "Le plus adapté : ses clients sont autour de chez lui.", "argumentaire": "Ses clients sont autour de chez lui. Fiche Google de la ferme ou du magasin, avis et itinéraire (M2.3), publications de saison et annonces de marchés (M2.1)."}, {"formation": "rs-video", "old": "Pour montrer la ferme et le travail au quotidien.", "new": "À proposer pour montrer la ferme, les produits et le travail au quotidien en vidéo (M3).", "argumentaire": ""}, {"formation": "rs-marque", "old": "Pour une marque de produits reconnaissable.", "new": "Pour une marque de produits reconnaissable.", "argumentaire": "Nom, logo et couleurs (M1 Socle)."}]$j$::jsonb, $j$M1 Base$j$, $j$Page pro avec produits, horaires et lieux de vente.$j$, $j$Choisir les réseaux adaptés à sa cible et créer ou optimiser une page professionnelle complète.$j$),
  ('rs-020', $j${"situation": "Photographe ou vidéaste indépendant(e).", "difficulte": "Marché concurrentiel ; style peu identifiable.", "attente": "Montrer son style et attirer les bons clients."}$j$::jsonb, $j$[{"formation": "rs-marque", "old": "Pour une signature visuelle reconnaissable.", "new": "Pour une signature visuelle reconnaissable.", "argumentaire": "Positionnement et identité qui reflètent son style (M1 Socle), et un portfolio en ligne."}, {"formation": "rs-video", "old": "Pour des formats courts adaptés aux réseaux.", "new": "Pour des formats courts adaptés aux réseaux.", "argumentaire": "Vertical et montage rapide sur smartphone (M3)."}]$j$::jsonb, $j$M1 Base$j$, $j$Choisir les réseaux où se trouvent ses clients, portfolio en ligne.$j$, $j$Choisir les réseaux adaptés à sa cible et créer ou optimiser une page professionnelle complète.$j$),
  ('rs-021', $j${"situation": "Organisateur(trice) d'événements ou wedding planner.", "difficulte": "Activité où l'on achète une émotion ; besoin de se démarquer.", "attente": "Donner envie avec ses réalisations et affirmer une image cohérente."}$j$::jsonb, $j$[{"formation": "rs-video", "old": "Pour faire vivre l'émotion des événements.", "new": "Pour faire vivre l'émotion des événements.", "argumentaire": "Vidéos d'ambiance et de coulisses tournées au smartphone (M3)."}, {"formation": "rs-marque", "old": "Pour une image haut de gamme et cohérente.", "new": "Pour une image haut de gamme et cohérente.", "argumentaire": "Positionnement et univers visuel de sa marque (M1 Socle)."}]$j$::jsonb, $j$M1 Base$j$, $j$Page pro qui présente ses prestations et ses réalisations.$j$, $j$Choisir les réseaux adaptés à sa cible et créer ou optimiser une page professionnelle complète.$j$),
  ('rs-022', $j${"situation": "Artiste, musicien(ne) ou auteur(e).", "difficulte": "Public difficile à construire ; dates et sorties peu relayées.", "attente": "Développer son public et annoncer ses dates et sorties."}$j$::jsonb, $j$[{"formation": "rs-marque", "old": "Pour une identité d'artiste reconnaissable.", "new": "Pour une identité d'artiste reconnaissable.", "argumentaire": "Univers, positionnement et charte visuelle (M1 Socle), avec un calendrier de publications autour des dates et sorties."}, {"formation": "rs-video", "old": "Pour partager extraits, concerts et coulisses.", "new": "À proposer pour partager extraits, teasers et coulisses filmés et montés au smartphone (M3).", "argumentaire": ""}]$j$::jsonb, $j$M1 Base$j$, $j$Choisir ses réseaux selon son public, page artiste complète.$j$, $j$Choisir les réseaux adaptés à sa cible et créer ou optimiser une page professionnelle complète.$j$),
  ('rs-023', $j${"situation": "Gère une franchise ou un point de vente d'enseigne.", "difficulte": "Doit attirer la clientèle locale dans le cadre fixé par l'enseigne.", "attente": "Rendre son point de vente visible localement en respectant la charte."}$j$::jsonb, $j$[{"formation": "rs-local", "old": "Le plus adapté : la visibilité de son point de vente.", "new": "Le plus adapté : la visibilité de son point de vente.", "argumentaire": "La visibilité de son point de vente. Fiche Google du magasin, avis et horaires à jour (M2.3), et publications locales dans le cadre fixé par l'enseigne."}, {"formation": "rs-simple", "old": "Si l'enseigne gère déjà la stratégie globale.", "new": "Si l'enseigne gère déjà la stratégie globale.", "argumentaire": "L'essentiel pour animer sa page locale."}]$j$::jsonb, $j$M1 Base$j$, $j$Page du point de vente, dans le cadre fixé par l'enseigne.$j$, $j$Choisir les réseaux adaptés à sa cible et créer ou optimiser une page professionnelle complète.$j$),
