  ('rs-025', $j${"situation": "Travaille en office de tourisme ou sur l'attractivité d'un territoire.", "difficulte": "Destination à faire connaître ; acteurs locaux à accompagner.", "attente": "Donner envie de venir et valoriser les lieux et acteurs du territoire."}$j$::jsonb, $j$[{"formation": "rs-video", "old": "Pour donner envie de venir avec des images du territoire.", "new": "Pour donner envie de venir avec des images du territoire.", "argumentaire": "Vidéos de lieux, d'activités et d'événements au smartphone (M3), avec un calendrier éditorial au fil des saisons."}, {"formation": "rs-local", "old": "Pour la visibilité des lieux et des acteurs locaux.", "new": "À proposer pour la visibilité des lieux et l'accompagnement des acteurs locaux sur leurs fiches Google (M2.3).", "argumentaire": ""}]$j$::jsonb, $j$M1 Base$j$, $j$Réseaux adaptés aux visiteurs et aux habitants.$j$, $j$Choisir les réseaux adaptés à sa cible et créer ou optimiser une page professionnelle complète.$j$),
  ('rs-026', $j${"situation": "Chargé(e) de développement économique (collectivité, réseau d'entreprises, chambre consulaire).", "difficulte": "Actions et dispositifs mal connus des entreprises.", "attente": "Être visible auprès des entreprises et des partenaires et relayer les actions."}$j$::jsonb, $j$[{"formation": "rs-linkedin", "old": "Le plus adapté : le réseau des entreprises.", "new": "Le plus adapté : le réseau des entreprises.", "argumentaire": "Le réseau des entreprises. Animer son réseau professionnel et relayer actions, dispositifs et réussites du territoire sur LinkedIn (M2.2)."}, {"formation": "rs-simple", "old": "Si l'objectif est d'abord de structurer la présence existante.", "new": "À proposer si l'objectif est d'abord de structurer la présence existante.", "argumentaire": ""}]$j$::jsonb, $j$M1 Base$j$, $j$Cibler entreprises, partenaires et porteurs de projet.$j$, $j$Choisir les réseaux adaptés à sa cible et créer ou optimiser une page professionnelle complète.$j$),
