  ('rs-028', $j${"situation": "Étudiant(e) ou jeune diplômé(e).", "difficulte": "Peu d'expérience, réseau limité, profil invisible des recruteurs.", "attente": "Être visible des recruteurs pour décrocher un stage, une alternance ou un premier emploi."}$j$::jsonb, $j$[{"formation": "rs-linkedin", "old": "Le réseau des recruteurs et des employeurs.", "new": "Le réseau des recruteurs et des employeurs.", "argumentaire": "Le réseau des recruteurs : profil LinkedIn optimisé, réseau et candidatures ciblées (M2.2), et partage de ses projets et compétences. Résultat : il est repéré pour un stage, une alternance ou un premier emploi."}]$j$::jsonb, $j$M1 Base$j$, $j$Définir sa cible : secteurs, entreprises, écoles.$j$, $j$Choisir les réseaux adaptés à sa cible et créer ou optimiser une page professionnelle complète.$j$),
  ('video-001', $j${"situation": "Chargé(e) de communication ou de marketing qui produit des vidéos pour l'entreprise.", "difficulte": "Montage mal maîtrisé ou sous-traité ; vidéos au rendu amateur.", "attente": "Produire en interne des vidéos professionnelles, montées et habillées."}$j$::jsonb, $j$[{"formation": "video-premiere", "old": "Le plus adapté : montage vidéo professionnel.", "new": "Le plus adapté : montage vidéo professionnel.", "argumentaire": "Monter, habiller (titres, sous-titres, musique) et exporter des vidéos professionnelles avec Premiere Pro. Résultat : des vidéos d'entreprise produites en interne."}, {"formation": "video-ia-avatar", "old": "Pour produire vite, sans tournage.", "new": "Pour produire vite, sans tournage.", "argumentaire": "Vidéos de présentation avec un avatar IA."}]$j$::jsonb, null, null, null),
