  ('video-004', $j${"situation": "Vidéaste ou créateur(trice) de contenu.", "difficulte": "Montage limité par ses outils actuels ; rendu à professionnaliser.", "attente": "Maîtriser un logiciel de montage professionnel pour chaque plateforme."}$j$::jsonb, $j$[{"formation": "video-premiere", "old": "Le plus adapté : le logiciel de montage de référence.", "new": "Le plus adapté : le logiciel de montage de référence.", "argumentaire": "Le logiciel de montage de référence. Montage avancé, son, titrage et export adapté à chaque plateforme."}]$j$::jsonb, null, null, null),
  ('web-001', $j${"situation": "Auto-entrepreneur ou TPE qui veut son site, ou le reprendre en main.", "difficulte": "Dépendance à un prestataire pour la moindre modification ; coûts.", "attente": "Créer et faire vivre son site soi-même."}$j$::jsonb, $j$[{"formation": "web-wordpress", "old": "Le plus adapté : créer son site soi-même.", "new": "Le plus adapté : créer son site soi-même.", "argumentaire": "Il crée et gère un site WordPress complet, en autonomie, avec certification Tosa. Résultat : plus besoin d'un prestataire pour chaque modification."}, {"formation": "web-geo-seo", "old": "Pour être trouvé une fois le site en ligne.", "new": "Pour être trouvé une fois le site en ligne.", "argumentaire": "Référencement naturel et contenus optimisés grâce à l'IA."}]$j$::jsonb, null, null, null),
  ('web-002', $j${"situation": "Gère le site et ses contenus.", "difficulte": "Visibilité insuffisante sur Google et dans les réponses des IA.", "attente": "Améliorer le référencement et produire des contenus efficaces."}$j$::jsonb, $j$[{"formation": "web-geo-seo", "old": "Le plus adapté : référencement et contenus.", "new": "Le plus adapté : référencement et contenus.", "argumentaire": "Stratégie éditoriale, SEO et visibilité dans les réponses des IA (GEO), avec des contenus produits grâce à l'IA. Résultat : un site plus visible."}, {"formation": "web-wordpress", "old": "S’il gère un site WordPress.", "new": "S’il gère un site WordPress.", "argumentaire": "Administration et évolution du site, avec certification Tosa."}]$j$::jsonb, null, null, null),
  ('web-003', $j${"situation": "Gère une boutique en ligne.", "difficulte": "Trafic insuffisant ; fiches produits peu visibles.", "attente": "Attirer plus de visiteurs grâce au référencement naturel."}$j$::jsonb, $j$[{"formation": "web-geo-seo", "old": "Le plus adapté : du trafic naturel vers la boutique.", "new": "Le plus adapté : du trafic naturel vers la boutique.", "argumentaire": "Fiches produits et contenus optimisés pour Google et les réponses des IA, pour du trafic naturel vers la boutique."}, {"formation": "web-wordpress", "old": "Pour gérer soi-même son site.", "new": "À proposer pour gérer et faire évoluer lui-même son site WordPress.", "argumentaire": ""}]$j$::jsonb, null, null, null),
  ('web-004', $j${"situation": "Rédacteur(trice) web ou créateur(trice) de contenu.", "difficulte": "Contenus qui ne se positionnent pas ; méthodes SEO en pleine évolution avec l'IA.", "attente": "Écrire des contenus bien positionnés, sur Google et dans les réponses des IA."}$j$::jsonb, $j$[{"formation": "web-geo-seo", "old": "Le plus adapté : rédaction optimisée avec l’IA.", "new": "Le plus adapté : rédaction optimisée avec l’IA.", "argumentaire": "Rédaction SEO, mots-clés et stratégie éditoriale assistées par l'IA, pour des contenus visibles sur Google et dans les réponses des IA."}]$j$::jsonb, null, null, null),
  ('ia-030', $j${"situation": "Gère le site et ses contenus : pages, articles, référencement.", "difficulte": "La visibilité ne dépend plus seulement de Google mais aussi des réponses des IA ; production de contenus chronophage.", "attente": "Produire plus vite des contenus bien référencés, visibles sur Google et dans les réponses des IA."}$j$::jsonb, $j$[{"formation": "ia-webmaster", "old": "Le plus adapté : référencement et contenus du site.", "new": "Le plus adapté : référencement et contenus du site.", "argumentaire": "Le M2 traite stratégie éditoriale et GEO-SEO, pour des pages et articles optimisés pour Google et pour les réponses des IA ; le M3 ajoute visuels et voix off pour habiller les contenus. Résultat : un site plus visible, alimenté plus vite."}, {"formation": "ia-graphiste", "old": "S'il produit aussi les visuels du site.", "new": "S'il produit aussi les visuels du site.", "argumentaire": "Prompts avancés au M2, bannières et illustrations avec Midjourney ou Ideogram, finalisées dans Photoshop, au M3."}]$j$::jsonb, $j$M1$j$, $j$Prendre en main ChatGPT, Claude, Mistral ou Gemini, les comparer et rédiger des prompts efficaces, sans exposer de données sensibles.$j$, $j$Comprendre le fonctionnement de l'IA générative, rédiger des prompts efficaces, comparer les outils (ChatGPT, Mistral, Gemini, Claude…) et adopter les bons réflexes : limites, éthique et sécurité des données.$j$),
  ('ia-031', $j${"situation": "Crée des visuels et des supports de communication pour des clients ou en interne.", "difficulte": "Délais courts, besoin de proposer plusieurs pistes ; inquiétude sur la qualité et les droits des images générées.", "attente": "Explorer plus de pistes créatives et livrer plus vite, en gardant la main sur le rendu final."}$j$::jsonb, $j$[{"formation": "ia-graphiste", "old": "Le plus adapté : textes et visuels avec les outils IA du design.", "new": "Le plus adapté : textes et visuels avec les outils IA du design.", "argumentaire": "Le M3 lui fait générer des pistes visuelles avec Midjourney et Ideogram et les finaliser dans Photoshop ; le M2 traite briefs, textes d'accompagnement et déclinaisons de campagnes. Les droits d'auteur des images générées sont abordés. Résultat : plus de pistes, des délais tenus, la main gardée sur le rendu."}]$j$::jsonb, $j$M1$j$, $j$Prendre en main ChatGPT, Claude, Mistral ou Gemini, les comparer et rédiger des prompts efficaces, sans exposer de données sensibles.$j$, $j$Comprendre le fonctionnement de l'IA générative, rédiger des prompts efficaces, comparer les outils (ChatGPT, Mistral, Gemini, Claude…) et adopter les bons réflexes : limites, éthique et sécurité des données.$j$),
  ('ia-032', $j${"situation": "Produit les campagnes, emailings, posts et visuels de la structure.", "difficulte": "Volume de contenus en hausse, équipe réduite ; cohérence avec la charte à préserver.", "attente": "Produire plus de contenus de qualité, textes et visuels, sans perdre en cohérence."}$j$::jsonb, $j$[{"formation": "ia-graphiste", "old": "Le plus adapté : visuels et contenus de campagne.", "new": "Le plus adapté : visuels et contenus de campagne.", "argumentaire": "Campagnes, emailings et posts au M2 avec des prompts avancés et des assistants ; visuels de campagne cohérents avec la charte au M3. Résultat : plus de contenus, sans perdre en qualité."}, {"formation": "ia-webmaster", "old": "Si le site et le référencement font partie de ses missions.", "new": "Si le site et le référencement font partie de ses missions.", "argumentaire": "Articles et pages optimisés pour Google et les IA au M2."}]$j$::jsonb, $j$M1$j$, $j$Prendre en main ChatGPT, Claude, Mistral ou Gemini, les comparer et rédiger des prompts efficaces, sans exposer de données sensibles.$j$, $j$Comprendre le fonctionnement de l'IA générative, rédiger des prompts efficaces, comparer les outils (ChatGPT, Mistral, Gemini, Claude…) et adopter les bons réflexes : limites, éthique et sécurité des données.$j$),
  ('pao-006', $j${"situation": "Monte catalogues, magazines, plaquettes ou documents longs pour l'impression.", "difficulte": "Gabarits, styles et exports d'impression mal maîtrisés ; retouches et logos à reprendre.", "attente": "Produire des documents prêts pour l'imprimeur, de façon fiable et rapide."}$j$::jsonb, $j$[{"formation": "pao-indesign", "old": "Le plus adapté : la mise en page professionnelle.", "new": "Le plus adapté : la mise en page professionnelle.", "argumentaire": "Gabarits, styles, longs documents et export PDF pour l'imprimeur, avec certification Tosa. Résultat : des documents fiables, produits plus vite."}, {"formation": "pao-illustrator", "old": "Pour les logos, pictos et illustrations vectorielles.", "new": "À proposer pour les logos, pictogrammes et illustrations vectorielles intégrés aux mises en page.", "argumentaire": ""}, {"formation": "pao-photoshop-perf", "old": "S'il maîtrise déjà les bases de Photoshop.", "new": "S'il maîtrise déjà les bases de Photoshop.", "argumentaire": "Détourages, photomontages et retouches avancées pour l'impression."}]$j$::jsonb, null, null, null),
  ('bur-004', $j${"situation": "Travaille avec des extractions d'ERP et des fichiers fournisseurs pour suivre stocks et achats.", "difficulte": "Données à nettoyer et croiser à la main, erreurs de ressaisie, suivi peu lisible.", "attente": "Consolider automatiquement ses données et suivre stocks et achats dans un tableau de bord fiable."}$j$::jsonb, $j$[{"formation": "bur-excel-power", "old": "Le plus adapté : importer, nettoyer et croiser des données.", "new": "Le plus adapté : importer, nettoyer et croiser des données.", "argumentaire": "Power Query consolide automatiquement les extractions ERP et fournisseurs, puis tableaux croisés et tableaux de bord donnent un suivi clair des stocks et des achats. Résultat : fini la ressaisie."}, {"formation": "bur-vba", "old": "Pour automatiser des traitements répétitifs.", "new": "Pour automatiser des traitements répétitifs.", "argumentaire": "Mises en forme, calculs et exports récurrents."}]$j$::jsonb, null, null, null),
  ('bur-005', $j${"situation": "Pilote son entreprise à partir des exports comptables et commerciaux.", "difficulte": "Chiffres dispersés, peu de visibilité sur marges et trésorerie, pas de temps pour construire des outils.", "attente": "Un tableau de bord simple et fiable pour suivre chiffre d'affaires, marges et trésorerie et décider plus vite."}$j$::jsonb, $j$[{"formation": "bur-excel-power", "old": "Le plus adapté : tableaux de bord et indicateurs.", "new": "Le plus adapté : tableaux de bord et indicateurs.", "argumentaire": "Il apprend à transformer ses exports comptables et commerciaux en indicateurs et graphiques mis à jour en un clic. Résultat : une vision claire de son activité pour décider plus vite."}]$j$::jsonb, null, null, null),
  ('video-005', $j${"situation": "Commercial(e) export ou chef(fe) de produit à l'international.", "difficulte": "Présenter offres et produits dans plusieurs langues, sans tournage ni traduction coûteuse.", "attente": "Produire des vidéos déclinées en plusieurs langues, rapidement."}$j$::jsonb, $j$[{"formation": "video-ia-avatar", "old": "Le plus adapté : vidéos avec avatar, déclinées en plusieurs langues.", "new": "Le plus adapté : vidéos avec avatar, déclinées en plusieurs langues.", "argumentaire": "Écrire le script, choisir l'avatar et la voix, puis décliner la même vidéo en plusieurs langues, sans tournage. Résultat : des présentations produit pour chaque marché."}, {"formation": "video-premiere", "old": "Pour monter des vidéos tournées sur le terrain ou en salon.", "new": "À proposer pour monter des vidéos tournées sur le terrain ou en salon.", "argumentaire": ""}]$j$::jsonb, null, null, null),
  ('cao-006', $j${"situation": "Conçoit jardins, terrasses et aménagements extérieurs pour des particuliers ou des entreprises.", "difficulte": "Les clients ont du mal à imaginer le résultat ; plans d'implantation à fournir aux entreprises.", "attente": "Présenter les projets en 3D pour convaincre, et produire des plans cotés."}$j$::jsonb, $j$[{"formation": "cao-sketchup", "old": "Le plus adapté : modéliser vite et présenter en 3D.", "new": "Le plus adapté : modéliser vite et présenter en 3D.", "argumentaire": "Modéliser terrain, terrasses et végétation et produire des vues 3D à montrer aux clients avant les travaux. Résultat : des projets plus convaincants."}, {"formation": "cao-autocad", "old": "Pour des plans cotés destinés aux entreprises.", "new": "À proposer pour fournir aux entreprises des plans d'implantation cotés et mis en page.", "argumentaire": ""}]$j$::jsonb, null, null, null),
  ('col-005', $j${"situation": "Commercial(e) ou technicien(ne) souvent en déplacement, en lien avec son équipe.", "difficulte": "Fichiers restés au bureau, comptes rendus à retaper, agendas non synchronisés.", "attente": "Accéder à ses fichiers, partager agendas et comptes rendus depuis son smartphone, en déplacement."}$j$::jsonb, $j$[{"formation": "col-workspace", "old": "Le plus adapté : Drive, Agenda et Meet sur ordinateur et smartphone.", "new": "Le plus adapté : Drive, Agenda et Meet sur ordinateur et smartphone.", "argumentaire": "Drive partagé, agendas d'équipe, visios Meet et documents coédités, sur ordinateur comme sur smartphone. Résultat : tout est accessible en déplacement."}, {"formation": "col-notion", "old": "Pour suivre ses clients et ses rendez-vous.", "new": "Pour suivre ses clients et ses rendez-vous.", "argumentaire": "Base clients et notes de visite au même endroit."}]$j$::jsonb, null, null, null),
  ('web-005', $j${"situation": "Association ou collectivité qui gère son site.", "difficulte": "Mises à jour dépendantes d'un prestataire ; site peu trouvé.", "attente": "Mettre à jour le site en autonomie et être bien trouvé."}$j$::jsonb, $j$[{"formation": "web-wordpress", "old": "Le plus adapté : prendre la main sur le site.", "new": "Le plus adapté : prendre la main sur le site.", "argumentaire": "Pages, actualités, agenda et médias mis à jour en autonomie, avec certification Tosa."}, {"formation": "web-geo-seo", "old": "Pour être mieux trouvé sur Google et par les IA.", "new": "Pour être mieux trouvé sur Google et par les IA.", "argumentaire": "Contenus pensés pour le référencement local et les réponses des IA."}]$j$::jsonb, null, null, null),
  ('com-005', $j${"situation": "Agent immobilier ou commercial(e) qui crée lui-même ses annonces et supports de vente.", "difficulte": "Supports peu soignés ou longs à produire, sans graphiste.", "attente": "Créer rapidement des annonces, fiches et présentations soignées, à son image."}$j$::jsonb, $j$[{"formation": "com-canva1", "old": "Le plus adapté : des visuels pros en une journée.", "new": "Le plus adapté : des visuels pros en une journée.", "argumentaire": "En une journée, il crée des modèles d'annonces, de fiches et de publications déclinés à partir de sa charte."}, {"formation": "com-canva-pro", "old": "Pour aller plus loin : charte, vidéo et IA.", "new": "Pour aller plus loin : charte, vidéo et IA.", "argumentaire": "Kit de marque, vidéos courtes et fonctions IA de Canva Pro."}]$j$::jsonb, null, null, null)
) as v(id, bd, pc, code, m1old, m1new)
where p.id = v.id;

-- Vérification : sous-profils avec besoin détaillé, parcours avec argumentaire détaillé
select (select count(*) from public.profils where data ? 'besoinDetail') as besoins_detailles,
       (select count(*) from public.profils p, jsonb_array_elements(p.data->'parcours') e where coalesce(e->>'argumentaire', '') <> '') as parcours_argumentes;
